insert into curriculum_topics values ('P2-physical-and-health-education-t1-w4','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',1,'4',4,'teaching',null,'Moving Our Body Parts (Part 4): Movement Patterns and Coordination','["Movement directions: forward, backward, sideways, up, down", "Movement speeds: fast and slow, starting and stopping", "Movement pathways: straight lines, curves, zigzag", "Body shapes: tall/stretched, wide/spread, small/curled, twisted", "Coordinating movements: marching (arms and legs together), crawling", "Simple rhythmic movements: clapping to beat, moving to music", "Activity: Movement to music, creative movement exploration"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,689) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t1-w5','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',1,'5',5,'midterm_assessment',null,'Mid-term Examination','["Practical assessment of body movements and coordination"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,690) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t1-w6','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',1,'6',6,'midterm_break',null,'Mid-term Break','["Holiday/Rest"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,690) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t1-w7','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',1,'7',7,'teaching',null,'Athletics: Running (Part 1)','["Understanding running: faster than walking, both feet off ground", "Proper running posture: body slightly forward, arms swinging, looking ahead", "Running techniques: lifting knees, landing on balls of feet", "Starting position: ready position, listening for signal", "Running in straight lines: staying in lane/path", "Short-distance running: 20-30 meters", "Activity: Running races, relay races (simple)"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,690) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t1-w8','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',1,'8',8,'teaching',null,'Athletics: Running (Part 2) and Jumping','["Running games: chase games, tag, \"What''s the time, Mr. Wolf?\"", "Starting and stopping on command", "Introduction to jumping: taking off and landing on two feet", "Types of jumps: jumping in place, jumping forward, jumping over low objects", "Jumping techniques: bending knees, swinging arms, soft landing", "Hopping: jumping on one foot", "Activity: Jumping games, hopscotch, jumping rope (introduction)"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,690) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t1-w9','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',1,'9',9,'teaching',null,'Games: Traditional/Local Games (Part 1)','["Understanding games: activities with rules, played for fun", "Nigerian traditional games: -\"Suwe\" (Hopscotch): drawing pattern, hopping in squares - \"Catcher\" (Tag): one person chases others - \"Hide and Seek\" (Oga): hiding and finding", "Rules of each game: how to play, how to win, fair play", "Taking turns and sharing", "Activity: Playing traditional games in small groups"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,690) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t1-w10','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',1,'10',10,'teaching',null,'Games: Traditional/Local Games (Part 2)','["More Nigerian games: -\"Ten-Ten\" (Clapping game): rhythmic hand clapping - \"Tinko-Tinko\" (Ball bouncing game) - \"Ayo\" or \"Ludo\" (Board games - introduction) - Skipping rope games", "Simple ball games: throwing and catching, rolling", "Importance of playing games: exercise, fun, making friends", "Being a good sport: not fighting, congratulating winners, trying again", "Activity: Class game tournament, rotating through different games"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,691) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t1-w11','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',1,'11',11,'revision',null,'Revision','["Review and practice: Body movements, running, jumping, local games"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,691) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t1-w12','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',1,'12',12,'examination',null,'Examination','["Practical assessment: Demonstrate movements, participate in games"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,691) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t1-w13','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',1,'13',13,'closing',null,'Closing/vacation','["Term ends"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,691) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t2-w1','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',2,'1',1,'teaching',null,'Swimming: Water Safety and Introduction (Part 1)','["Understanding swimming: moving through water", "Importance of swimming: exercise, water safety skill, fun", "Water safety rules: - Never swim alone, always with adult - Only swim in safe places: pools, shallow areas - Don''t run near water - Listen to lifeguard/adult instructions", "Dangers of deep water", "What to do if someone is drowning: call for help, don''t jump in", "Activity: Water safety posters, discussing safety rules"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,692) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t2-w2','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',2,'2',2,'teaching',null,'Swimming: Water Familiarization (Part 2)','["Getting comfortable with water (if pool available): - Splashing face with water - Wetting hair and body gradually - Walking in shallow water - Sitting in shallow water", "If no pool: Simulating movements on land", "Overcoming fear of water: gradual exposure, games", "Water games: splashing gently, catching objects in shallow water", "Floating aids: arm bands, kickboards, life jackets", "Activity: Water play activities (supervised), land-based swimming movements"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,692) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t2-w3','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',2,'3',3,'teaching',null,'Swimming: Basic Water Skills (Part 3)','["Blowing bubbles: in water, making bubbles with mouth", "Holding breath: taking deep breath, underwater for few seconds (if pool available)", "Floating practice: lying on back with support, relaxing in water", "Kicking movements: sitting on edge, kicking legs in water", "Arm movements: paddling, scooping water", "If no pool available: Practicing movements on benches/mats", "Activity: Water confidence activities, movement practice"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,692) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t2-w4','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',2,'4',4,'teaching',null,'Swimming: Swimming Safety Review and Fun (Part 4)','["Review of all water safety rules", "Swimming pool rules: no pushing, no running, shower before entering", "Recognizing dangerous situations near water", "Emergency procedures: calling for help, throwing floatation device", "Swimming as exercise: good for whole body", "Fun water activities and games (supervised)", "Activity: Water safety quiz, safe swimming practices demonstration"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,692) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t2-w5','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',2,'5',5,'midterm_assessment',null,'Mid-term Examination','["Assessment of Weeks 1-4 (Written water safety, practical if pool available)"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,693) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t2-w6','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',2,'6',6,'midterm_break',null,'Mid-term Break','["Holiday/Rest"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,693) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t2-w7','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',2,'7',7,'teaching',null,'Health and Hygiene (Part 1): Personal Cleanliness','["Understanding hygiene: keeping our body clean and healthy", "Daily hygiene practices: - Bathing daily: morning and/or evening -Washing hands: before eating, after toilet, after playing - Brushing teeth: morning and night, after meals - Washing face: morning and evening - Cutting nails: keeping them short and clean", "Proper handwashing steps: wet, soap, scrub (20 seconds), rinse, dry", "Activity: Handwashing practice, demonstrating hygiene routines"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,693) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t2-w8','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',2,'8',8,'teaching',null,'Health and Hygiene (Part 2): Body Care','["Hair care: washing regularly, combing, keeping tidy", "Ear care: cleaning outer ear gently, not putting objects inside", "Nose care: blowing nose with tissue, keeping clean", "Clothing hygiene: wearing clean clothes daily, changing underwear", "Foot care: washing feet, wearing clean socks, proper shoes", "Why hygiene is important: staying healthy, smelling good, preventing diseases", "Diseases from poor hygiene: stomach ache, skin infections, lice", "Activity: Hygiene checklist, role-playing daily hygiene routines"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,693) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t2-w9','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',2,'9',9,'teaching',null,'Health and Hygiene (Part 3): Food and Environmental Hygiene','["Food hygiene: - Washing hands before eating - Eating clean, well-cooked food - Washing fruits and vegetables - Not eating food that has fallen on ground - Covering food from flies and insects", "Drinking clean water: boiled or filtered water", "Environmental hygiene: - Keeping surroundings clean - Using dustbins for rubbish - Not littering", "Activity: Clean-up exercise in classroom/school compound"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,693) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t2-w10','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',2,'10',10,'teaching',null,'Health and Hygiene (Part 4): Toilet Hygiene and Healthy Habits','["Proper use of toilet: sitting properly, flushing, cleaning", "Handwashing after using toilet (review and emphasis)", "Keeping toilet clean: not throwing paper everywhere, telling adult if problems", "Healthy habits: - Getting enough sleep: 9-10 hours for children -Eating healthy food: fruits, vegetables, balanced meals - Drinking enough water - Exercising/playing daily", "Activity: Creating \"Healthy Habits\" poster, daily routine planning"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,694) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t2-w11','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',2,'11',11,'revision',null,'Revision','["Review: Swimming safety, hygiene practices, healthy habits"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,694) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t2-w12','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',2,'12',12,'examination',null,'Examination','["Written and oral assessment on health and hygiene"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,694) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t2-w13','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',2,'13',13,'closing',null,'Closing/vacation','["Term ends"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,694) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t3-w1','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',3,'1',1,'teaching',null,'First Aid: Understanding First Aid','["What is first aid? Help given immediately when someone is hurt or sick", "Why first aid is important: stops pain, prevents worse injury, helps until doctor comes", "When we need first aid: cuts, bruises, nose bleeding, burns, insect bites, sprains", "Who can give first aid: adults, trained people, teachers, school nurse", "First aid rule: Always call an adult for help", "Staying calm when someone is hurt", "Activity: Role-play calling for help, discussing emergency scenarios"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,695) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t3-w2','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',3,'2',2,'teaching',null,'First Aid: The First Aid Box','["What is a first aid box? Box with items for treating injuries", "Contents of first aid box: - Bandages and plasters (for covering cuts) - Cotton wool (for cleaning wounds) - Antiseptic liquid/cream (for cleaning cuts) - Scissors (for cutting bandages) - Thermometer (for checking temperature) - Safety pins", "Where to find first aid boxes: school clinic, home, car", "Never play with first aid items", "Activity: Identifying first aid items, creating class first aid poster"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,695) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t3-w3','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',3,'3',3,'teaching',null,'First Aid: Treating Minor Injuries (Part 1)','["Treating small cuts and scrapes: 1. Tell an adult immediately 2. Clean with clean water 3. Apply antiseptic (adult does this) 4. Cover with plaster or bandage", "Treating bruises: - Apply cold compress (ice pack or cold cloth) - Rest the hurt part", "What NOT to do: - Don''t touch wound with dirty hands - Don''t remove bandage too soon", "Activity: Demonstrating on dolls, practicing calling for help"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,695) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t3-w4','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',3,'4',4,'teaching',null,'First Aid: Treating Minor Injuries (Part 2)','["Treating nose bleeding: - Sit upright, don''t lie down - Lean forward slightly - Pinch soft part of nose - Breathe through mouth - Get adult help", "Treating insect bites/stings: - Don''t scratch - Wash with soap and water - Apply cream (adult does this) - Tell adult if swelling or pain", "Treating minor burns (from hot water, sun): - Run cool water over burn - Don''t apply ice directly - Cover with clean cloth - Get adult help immediately", "Activity: First aid scenarios, what would you do?"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,695) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t3-w5','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',3,'5',5,'midterm_assessment',null,'Mid-term Examination','["Assessment of Weeks 1-4 (First aid knowledge and procedures)"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,696) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t3-w6','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',3,'6',6,'midterm_break',null,'Mid-term Break','["Holiday/Rest"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,696) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t3-w7','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',3,'7',7,'teaching',null,'Safety Education: Home Safety','["Safety in the home: -Kitchen: don''t touch hot stove, sharp knives, don''t play near fire - Bathroom: careful on wet floor, don''t play with medicine -Bedroom: don''t jump on bed, keep floor clear of toys -Living room: don''t play with electrical sockets, careful with sharp corners", "Dangers at home: fire, electricity, sharp objects, poisonous substances", "What to do in emergency: call adult, know parents'' phone numbers", "Activity: Home safety picture identification, creating safety rules poster"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,696) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t3-w8','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',3,'8',8,'teaching',null,'Safety Education: School Safety','["Safety at school: -Classroom: sit properly, don''t run, keep bags under desk - Playground: play gently, don''t push, use equipment properly -Stairs: hold handrail, walk don''t run, one step at a time -Toilets: careful on wet floor, close doors properly", "Playing safely: no rough play, no fighting, take turns", "Reporting dangers: broken equipment, spills, strangers", "Assembly safety: walk in line, don''t push", "Activity: School safety walk, identifying hazards and solutions"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,696) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t3-w9','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',3,'9',9,'teaching',null,'Safety Education: Road Safety','["Understanding roads: where vehicles move", "Dangers on roads: moving cars, motorcycles, bicycles", "Road safety rules: - Always hold adult''s hand near roads - Look left, right, left before crossing - Use pedestrian crossing (zebra crossing) - Walk on pavement/sidewalk, not on road - Never play on or near roads", "Traffic lights: red (stop), yellow (get ready), green (go)", "Activity: Road safety role-play, crossing practice (in safe area)"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,697) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t3-w10','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',3,'10',10,'teaching',null,'Safety Education: Personal Safety and Emergency Numbers','["Stranger danger: - Don''t talk to strangers - Don''t follow strangers - Don''t accept gifts from strangers - Don''t go anywhere with strangers - Scream and run if stranger tries to take you", "Safe adults: parents, teachers, police, trusted family members", "Getting lost: stay where you are, find police/security, know your name and parents'' names", "Emergency numbers in Nigeria: - 112 (general emergency) - 767 (police - in some states) - 199 (fire service)", "Activity: Practicing emergency calls (pretend), memorizing important information"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,697) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t3-w11','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',3,'11',11,'revision',null,'Revision','["Comprehensive review: First aid, home safety, school safety, road safety, personal safety"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,697) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t3-w12','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',3,'12',12,'examination',null,'Examination','["End of Term Assessment (Written and oral on safety and first aid)"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,697) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t3-w13','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',3,'13',13,'closing',null,'Closing/vacation','["Term ends - End of Primary 2"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,697) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-christian-religious-studies-t1-w1','ng-scheme-2025-preprimary-primary','P2','christian-religious-studies',1,'1',1,'teaching',null,'The Meaning of Prayer (Part 1)','["What is prayer? Talking to God", "Prayer is like talking to our parent or friend", "God listens when we pray", "We can pray anywhere: home, school, church, playground", "We can pray anytime: morning, afternoon, night", "God loves it when we pray", "Simple explanation: Prayer is our conversation with God", "Activity: Discussing who we talk to and how prayer is talking to God"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,698) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-christian-religious-studies-t1-w2','ng-scheme-2025-preprimary-primary','P2','christian-religious-studies',1,'2',2,'teaching',null,'The Meaning of Prayer (Part 2)','["Different ways to pray: - Speaking out loud - Praying silently in our hearts - Singing songs to God - Reading prayers from the Bible", "Prayer positions: standing, sitting, kneeling, bowing head", "Folding hands and closing eyes helps us concentrate", "God hears all our prayers, however we pray", "Activity: Practicing different prayer positions, singing prayer songs"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,698) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-christian-religious-studies-t1-w3','ng-scheme-2025-preprimary-primary','P2','christian-religious-studies',1,'3',3,'teaching',null,'When to Pray (Part 1)','["We can pray anytime we want", "Special times to pray: -Morning prayers: thanking God for the night, asking for protection -Before meals: thanking God for food (saying grace) -Night prayers: thanking God for the day, asking for peaceful sleep", "The Bible says \"Pray without ceasing\" (1 Thessalonians 5:17 - simple)", "Activity: Learning morning, meal, and bedtime prayers"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,698) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-christian-religious-studies-t1-w4','ng-scheme-2025-preprimary-primary','P2','christian-religious-studies',1,'4',4,'teaching',null,'When to Pray (Part 2)','["Other times to pray: -Before going to school: asking God for wisdom and safety - When we are happy: thanking God -When we are sad or afraid: asking God for help and comfort - When we need something: asking God - When someone is sick: praying for healing - Before exams/tests: asking for understanding", "We should pray every day", "Activity: Creating a daily prayer schedule, discussing when we pray at home"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,698) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-christian-religious-studies-t1-w5','ng-scheme-2025-preprimary-primary','P2','christian-religious-studies',1,'5',5,'midterm_assessment',null,'Mid-term Examination','["Assessment of Weeks 1-4"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,699) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-christian-religious-studies-t1-w6','ng-scheme-2025-preprimary-primary','P2','christian-religious-studies',1,'6',6,'midterm_break',null,'Mid-term Break','["Holiday/Rest"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,699) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-christian-religious-studies-t1-w7','ng-scheme-2025-preprimary-primary','P2','christian-religious-studies',1,'7',7,'teaching',null,'How to Pray (Part 1): The Lord''s Prayer Introduction','["Jesus taught us how to pray", "The Lord''s Prayer: \"Our Father who art in heaven...\"", "Learning the Lord''s Prayer line by line (first part): -\"Our Father who art in heaven\" (God is our loving Father in heaven) - \"Hallowed be thy name\" (God''s name is holy and special) - \"Thy kingdom come\" (We want God to rule) -\"Thy will be done on earth as it is in heaven\" (We want to obey God)", "Simple explanation of each line", "Activity: Memorizing first part of Lord''s Prayer with actions"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,699) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-christian-religious-studies-t1-w8','ng-scheme-2025-preprimary-primary','P2','christian-religious-studies',1,'8',8,'teaching',null,'How to Pray (Part 2): The Lord''s Prayer Continued','["Learning the Lord''s Prayer (second part): -\"Give us this day our daily bread\" (Asking God for what we need) -\"And forgive us our trespasses\" (Asking God to forgive our sins) - \"As we forgive those who trespass against us\" (We must forgive others) -\"And lead us not into temptation\" (Help us not to do wrong) - \"But deliver us from evil\" (Protect us from bad things) -\"For thine is the kingdom, the power, and the glory, forever. Amen\"", "Activity: Reciting complete Lord''s Prayer, drawing prayer scenes"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,699) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-christian-religious-studies-t1-w9','ng-scheme-2025-preprimary-primary','P2','christian-religious-studies',1,'9',9,'teaching',null,'How to Pray (Part 3): Parts of Prayer','["Four main parts of prayer (ACTS): -Adoration: Praising God (God, you are great and wonderful!) - Confession: Saying sorry for wrong things we did - Thanksgiving: Thanking God for His blessings - Supplication: Asking God for what we need", "We can pray for ourselves and for others", "Being honest with God: He knows everything", "Activity: Creating simple prayers using ACTS format"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,699) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-christian-religious-studies-t1-w10','ng-scheme-2025-preprimary-primary','P2','christian-religious-studies',1,'10',10,'teaching',null,'How to Pray (Part 4): Prayer in Action','["Examples of people who prayed in the Bible: - Jesus prayed often - David prayed and wrote psalms - Daniel prayed three times a day", "God answers prayers: Yes, No, or Wait", "We must have faith when we pray (believe God hears us)", "Praying for others: family, friends, teachers, leaders", "Activity: Writing simple prayers, class prayer time, prayer chain"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,700) on conflict (id) do nothing;
