insert into curriculum_topics values ('P2-christian-religious-studies-t2-w1','ng-scheme-2025-preprimary-primary','P2','christian-religious-studies',2,'1',1,'teaching',null,'Jesus'' Power Over Natural Forces (Part 1): Jesus Calms the Storm','["Story: Jesus and disciples in a boat on the sea (Mark 4:35-41)", "A big storm came: strong wind, big waves, boat filling with water", "Disciples were afraid: \"We are going to drown!\"", "Jesus was sleeping in the boat", "They woke Jesus: \"Teacher, don''t you care that we are dying?\"", "Jesus stood up and said to the storm: \"Peace! Be still!\"", "The wind stopped, the sea became calm", "Jesus asked: \"Why are you afraid? Do you have no faith?\"", "Lesson: Jesus has power over nature (wind and waves)", "Activity: Acting out the story, drawing the scene, discussing what we learn"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,701) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-christian-religious-studies-t2-w2','ng-scheme-2025-preprimary-primary','P2','christian-religious-studies',2,'2',2,'teaching',null,'Jesus'' Power Over Natural Forces (Part 2): Jesus Walks on Water','["Story: Jesus walks on water (Matthew 14:22-33)", "Disciples in boat at night, Jesus on land praying", "Jesus walked on the water toward the boat", "Disciples were frightened: \"It''s a ghost!\"", "Jesus said: \"It is I. Don''t be afraid.\"", "Peter wanted to walk on water too", "Peter walked on water but got scared and started to sink", "Jesus saved Peter", "Lesson: Jesus can do what is impossible for us; we must have faith", "Activity: Retelling story, discussing miracles, water experiments (things that float/sink)"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,701) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-christian-religious-studies-t2-w3','ng-scheme-2025-preprimary-primary','P2','christian-religious-studies',2,'3',3,'teaching',null,'Jesus'' Power Over Natural Forces (Part 3): Jesus Feeds 5,000 People','["Story: Jesus feeds 5,000 people (John 6:1-14)", "Many people followed Jesus to hear Him teach", "It was late, people were hungry", "A boy had 5 loaves of bread and 2 fish", "Jesus took the food, prayed, and gave thanks to God", "Jesus gave the food to disciples to share", "Everyone ate and was satisfied", "There were 12 baskets of leftovers!", "Lesson: Jesus can multiply what we have; sharing is important", "Activity: Counting exercise (5 loaves, 2 fish, 12 baskets), discussing sharing"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,701) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-christian-religious-studies-t2-w4','ng-scheme-2025-preprimary-primary','P2','christian-religious-studies',2,'4',4,'teaching',null,'Jesus'' Power Over Diseases (Part 1): Jesus Heals the Sick','["Jesus healed many sick people", "Story: Jesus heals a man with leprosy (Matthew 8:1-4) - Man with leprosy came to Jesus -He said: \"Lord, if you want, you can make me clean\" -Jesus touched him and said: \"I am willing. Be clean!\" - The man was healed immediately", "Story: Jesus heals Peter''s mother-in-law (fever)", "Lesson: Jesus cares about sick people and can heal them", "Activity: Role-playing healing stories, making get-well cards"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,702) on conflict (id) do nothing;
