insert into curriculum_topics values ('P2-christian-religious-studies-t2-w7','ng-scheme-2025-preprimary-primary','P2','christian-religious-studies',2,'7',7,'teaching',null,'Jesus'' Power Over Diseases (Part 2): More Healing Miracles','["Story: Jesus heals a paralyzed man (Mark 2:1-12) - Four friends brought paralyzed man to Jesus - House was too crowded -They made a hole in the roof and lowered their friend -Jesus said: \"Your sins are forgiven. Get up and walk!\" - The man stood up, picked up his mat, and walked", "Story: Jesus heals blind Bartimaeus (Mark 10:46-52)", "Lesson: Faith in Jesus brings healing; good friends help each other", "Activity: Discussing importance of friends, acting out stories"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,702) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-christian-religious-studies-t2-w8','ng-scheme-2025-preprimary-primary','P2','christian-religious-studies',2,'8',8,'teaching',null,'Jesus'' Power Over Death (Part 1): Jesus Raises Jairus'' Daughter','["Story: Jairus'' daughter raised from the dead (Mark 5:21-43)", "Jairus was a synagogue leader, his daughter was very sick", "He asked Jesus to come and heal her", "While they were going, news came: \"Your daughter is dead\"", "Jesus said: \"Don''t be afraid, just believe\"", "They went to the house, people were crying", "Jesus said: \"She is not dead, she is sleeping\"", "Jesus said: \"Little girl, get up!\" and she got up", "Lesson: Jesus has power over death; nothing is impossible for Jesus", "Activity: Storytelling with pictures, discussing Jesus'' power"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,702) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-christian-religious-studies-t2-w9','ng-scheme-2025-preprimary-primary','P2','christian-religious-studies',2,'9',9,'teaching',null,'Jesus'' Power Over Death (Part 2): Jesus Raises Lazarus','["Story: Jesus raises Lazarus from the dead (John 11:1-44)", "Lazarus was Jesus'' friend, he was very sick", "Lazarus died and was buried for four days", "Jesus came to Bethany", "Martha and Mary were sad", "Jesus said: \"I am the resurrection and the life\"", "Jesus went to the tomb and said: \"Lazarus, come out!\"", "Lazarus came out, alive!", "Lesson: Jesus gives life; Jesus cares about our sadness", "Activity: Retelling story, discussing how Jesus comforts us"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,702) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-christian-religious-studies-t2-w10','ng-scheme-2025-preprimary-primary','P2','christian-religious-studies',2,'10',10,'teaching',null,'Jesus'' Power Over Evil People','["Story: Jesus cleanses the temple (Matthew 21:12-13) - People were buying and selling in God''s temple - They were cheating people - Jesus was angry at the wrong behavior -He drove them out and said: \"My house shall be called a house of prayer\"", "Jesus stood against evil and wrong behavior", "Jesus was strong but also kind", "Lesson: Jesus wants us to respect God''s house; do what is right", "Activity: Discussing right and wrong behavior, respecting church/places of worship"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,703) on conflict (id) do nothing;
