insert into curriculum_topics values ('P2-christian-religious-studies-t3-w1','ng-scheme-2025-preprimary-primary','P2','christian-religious-studies',3,'1',1,'teaching',null,'Abraham (Part 1): God''s Promise to Abraham','["Who was Abraham? A man who loved and obeyed God", "Abraham lived in a place called Ur", "God spoke to Abraham: \"Leave your country and go to a land I will show you\"", "God''s promises to Abraham: - \"I will make you a great nation\" - \"I will bless you\" - \"You will be a blessing to others\" - \"I will give this land to your descendants\"", "Abraham obeyed God and left his home", "Lesson: God makes promises and keeps them; we should obey God", "Activity: Drawing Abraham''s journey, map activity"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,704) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-christian-religious-studies-t3-w2','ng-scheme-2025-preprimary-primary','P2','christian-religious-studies',3,'2',2,'teaching',null,'Abraham (Part 2): The Birth of Isaac','["Abraham and Sarah had no children, they were old", "God promised them a son", "Sarah laughed because she was too old", "But God said: \"Nothing is impossible with God\"", "When Abraham was 100 years old, Isaac was born!", "God kept His promise", "Isaac means \"laughter\" - they were so happy", "Lesson: God keeps His promises even when it seems impossible; God''s timing is perfect", "Activity: Discussing waiting for promises, celebrating with drawing/songs"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,704) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-christian-religious-studies-t3-w3','ng-scheme-2025-preprimary-primary','P2','christian-religious-studies',3,'3',3,'teaching',null,'Abraham (Part 3): God Tests Abraham''s Faith','["Story: Abraham and Isaac (Genesis 22:1-18 - age-appropriate version)", "God tested Abraham''s faith", "God asked Abraham to offer Isaac", "Abraham loved Isaac but he loved and trusted God more", "Abraham obeyed and took Isaac to the mountain", "When Abraham was about to obey, God stopped him", "God provided a ram instead", "God said: \"Now I know you fear God\"", "God blessed Abraham for his obedience", "Lesson: True faith means obeying God completely; God provides what we need", "Activity: Discussing obedience, trust in God"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,704) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-christian-religious-studies-t3-w4','ng-scheme-2025-preprimary-primary','P2','christian-religious-studies',3,'4',4,'teaching',null,'Deliverance from Egypt (Part 1): The Israelites in Egypt','["Abraham''s family grew into a large nation (Israelites)", "They went to Egypt because of famine", "At first, Egyptians were kind to them", "Later, a new Pharaoh made them slaves", "The Israelites worked hard: making bricks, building", "They were treated badly", "The Israelites cried to God for help", "God heard their prayers and remembered His promise to Abraham", "Lesson: God hears our prayers when we cry to Him", "Activity: Discussing how God helps people in trouble, prayer time"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,704) on conflict (id) do nothing;
