insert into curriculum_topics values ('P2-christian-religious-studies-t3-w7','ng-scheme-2025-preprimary-primary','P2','christian-religious-studies',3,'7',7,'teaching',null,'Deliverance from Egypt (Part 2): Moses and the Burning Bush','["God chose Moses to deliver the Israelites", "Moses was keeping sheep in the wilderness", "He saw a bush on fire but it didn''t burn up", "God spoke to Moses from the bush", "God said: \"I have seen my people suffering in Egypt\"", "\"I am sending you to Pharaoh to bring my people out\"", "Moses was afraid but God promised to be with him", "Lesson: God calls people to help others; God is always with us", "Activity: Acting out the burning bush scene, discussing being brave"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,705) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-christian-religious-studies-t3-w8','ng-scheme-2025-preprimary-primary','P2','christian-religious-studies',3,'8',8,'teaching',null,'Deliverance from Egypt (Part 3): The Passover and Crossing the Red Sea','["Moses went to Pharaoh: \"Let my people go!\"", "Pharaoh refused many times", "God sent plagues (troubles) on Egypt", "The last plague: Passover (God protected Israelites)", "Finally, Pharaoh let them go", "The Israelites left Egypt (the Exodus)", "Pharaoh changed his mind and chased them", "They reached the Red Sea - trapped!", "Moses stretched his hand, God parted the sea", "The Israelites walked through on dry ground", "The Egyptian army was defeated", "Lesson: God delivers His people; God is more powerful than any enemy", "Activity: Creating Red Sea crossing scene, retelling with actions"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,705) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-christian-religious-studies-t3-w9','ng-scheme-2025-preprimary-primary','P2','christian-religious-studies',3,'9',9,'teaching',null,'Entry into the Promised Land (Part 1): Journey to Canaan','["God led the Israelites through the wilderness", "They were going to Canaan, the Promised Land", "God provided for them: - Manna (bread from heaven) every morning - Quail (birds) for meat - Water from a rock - Cloud by day, fire by night (God''s presence)", "The journey was long (40 years) because of disobedience", "Moses led them but Joshua took over later", "Lesson: God provides for His people; obedience is important", "Activity: Discussing God''s provision, creating wilderness journey poster"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,705) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-christian-religious-studies-t3-w10','ng-scheme-2025-preprimary-primary','P2','christian-religious-studies',3,'10',10,'teaching',null,'Entry into the Promised Land (Part 2): Crossing the Jordan and Entering Canaan','["Joshua became the new leader", "God spoke to Joshua: \"Be strong and courageous\"", "The Israelites reached the Jordan River", "God made the water stop flowing", "They walked across on dry ground (like the Red Sea)", "They entered the Promised Land - Canaan!", "God kept His promise to Abraham", "Jerusalem became their special city later", "Story: The walls of Jericho fell down (God''s power)", "Lesson: God always keeps His promises; be strong and trust God", "Activity: Building and knocking down Jericho walls (blocks), celebrating God''s faithfulness"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,706) on conflict (id) do nothing;
