insert into curriculum_topics values ('P2-islamic-studies-t2-w3','ng-scheme-2025-preprimary-primary','P2','islamic-studies',2,'3',3,'teaching',null,'Brief History of Prophet Musa (AS)','["Who was Prophet Musa (Moses)?", "The bad king: Fir''awn (Pharaoh)", "Pharaoh was mean to the people", "Baby Musa is born", "Pharaoh wanted to kill baby boys", "Musa''s mother puts him in a basket", "The basket floats on the river", "Allah protects baby Musa", "Pharaoh''s wife finds the basket", "She wants to keep baby Musa", "Baby Musa goes back to his mother", "Allah''s wonderful plan"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,709) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-islamic-studies-t2-w4','ng-scheme-2025-preprimary-primary','P2','islamic-studies',2,'4',4,'teaching',null,'Brief History of Prophet Musa (AS)','["Musa grows up in the palace", "Musa leaves Egypt and goes to Madyan", "Musa helps two girls at a well", "Musa becomes a shepherd", "Allah speaks to Musa from a burning bush", "Allah tells Musa: \"Go to Pharaoh\"", "Musa gets help from his brother Harun", "Musa''s special miracles: Staff turns into snake, shining hand", "Musa goes to Pharaoh: \"Let my people go\"", "Pharaoh says \"No!\"", "The contest with magicians", "Magicians believe in Allah"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,709) on conflict (id) do nothing;
