insert into curriculum_topics values ('P2-islamic-studies-t2-w7','ng-scheme-2025-preprimary-primary','P2','islamic-studies',2,'7',7,'teaching',null,'Brief History of Prophet Musa (AS)','["Musa leads people out of Egypt", "Pharaoh chases them with his army", "They reach the Red Sea", "People are scared", "Musa says: \"Allah will help us\"", "The sea splits into two!", "People walk through safely", "Pharaoh tries to follow", "The sea closes and Pharaoh drowns", "Allah saves Musa and the people", "Lessons: Trust Allah, be brave, Allah helps good people"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,710) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-islamic-studies-t2-w8','ng-scheme-2025-preprimary-primary','P2','islamic-studies',2,'8',8,'teaching',null,'Brief History of Prophet Isa (AS)','["Who was Prophet Isa (Jesus)?", "Maryam (Mary): A very good woman", "Maryam loved to pray", "Angel Jibreel visits Maryam", "Allah gives Maryam a baby (miracle - no father)", "Baby Isa is born", "Allah sends dates and water for Maryam", "People ask questions", "Baby Isa speaks from the cradle!", "Baby Isa says: \"I am Allah''s servant\"", "Everyone is amazed", "Lesson: Allah can do anything"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,710) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-islamic-studies-t2-w9','ng-scheme-2025-preprimary-primary','P2','islamic-studies',2,'9',9,'teaching',null,'Brief History of Prophet Isa (AS)','["Isa grows up as a good boy", "Isa loves his mother Maryam", "Isa becomes a Prophet", "Isa''s message: Worship only Allah", "Isa''s miracles (with Allah''s permission): o Making clay birds come alive o Healing sick people o Helping blind people see", "Many people believe in Isa", "Some people didn''t like Isa", "Allah protects Prophet Isa", "Lessons: Be kind, help others, listen to Prophets"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,710) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-islamic-studies-t2-w10','ng-scheme-2025-preprimary-primary','P2','islamic-studies',2,'10',10,'teaching',null,'Brief History of Prophet Muhammad (SAW) - Birth','["Arabia before Prophet Muhammad (SAW)", "The Year of the Elephant", "Prophet Muhammad is born in Makkah", "His father Abdullah (died before he was born)", "His mother Aminah", "Special signs on the night he was born", "His grandfather Abdul-Muttalib", "Baby Muhammad goes to live in the desert", "His nurse Halima looks after him", "Blessings come to Halima''s family", "Young Muhammad returns to his mother"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,710) on conflict (id) do nothing;
