insert into curriculum_topics values ('P2-islamic-studies-t3-w1','ng-scheme-2025-preprimary-primary','P2','islamic-studies',3,'1',1,'teaching',null,'Brief History of Prophet Muhammad (SAW) - Childhood','["Muhammad''s mother Aminah dies (he is 6 years old)", "Muhammad becomes an orphan", "His grandfather takes care of him", "Abdul-Muttalib loves Muhammad very much", "Grandfather dies (Muhammad is 8 years old)", "His uncle Abu Talib takes care of him", "Abu Talib is kind and loving", "Young Muhammad works as a shepherd", "He looks after sheep and goats", "Muhammad is honest and kind", "Everyone trusts him", "People call him \"Al-Ameen\" (The Trustworthy)"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,712) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-islamic-studies-t3-w2','ng-scheme-2025-preprimary-primary','P2','islamic-studies',3,'2',2,'teaching',null,'Brief History of Prophet Muhammad (SAW) - Youth to Marriage','["Muhammad grows up to be a young man", "He is known for being honest", "He never lies or cheats", "He helps people solve problems", "Muhammad becomes a trader", "He travels to buy and sell goods", "A rich woman named Khadijah", "Khadijah needs someone to trade for her", "Muhammad works for Khadijah", "He is very honest and hardworking", "Khadijah is impressed by Muhammad", "Khadijah wants to marry Muhammad", "Muhammad marries Khadijah", "They love each other very much", "They have children together"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,712) on conflict (id) do nothing;
