insert into curriculum_topics values ('P2-nigerian-history-t1-w1','ng-scheme-2025-preprimary-primary','P2','nigerian-history',1,'1',1,'teaching',null,'What is History?','["What is history?", "History tells us about the past", "Things that happened long ago", "Learning about people who lived before us", "Why we study history", "History helps us understand today", "Learning from the past", "Stories of our ancestors", "Activity: Sharing family stories", "Discussion: What do we want to know about the past?"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,715) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-nigerian-history-t1-w2','ng-scheme-2025-preprimary-primary','P2','nigerian-history',1,'2',2,'teaching',null,'Sources of History','["What are sources of history?", "How we learn about the past", "Oral sources (stories told by elders, songs, poems)", "Written sources (books, letters, newspapers)", "Physical sources (old buildings, monuments, artifacts)", "Pictures and photographs", "Museums and what we find there", "Visiting historical places", "Activity: Bringing old family photos to class", "Creating a simple class timeline"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,715) on conflict (id) do nothing;
