insert into curriculum_topics values ('P2-nigerian-history-t1-w7','ng-scheme-2025-preprimary-primary','P2','nigerian-history',1,'7',7,'teaching',null,'How People Came to Nigeria','["People moved from place to place", "Migration (moving to new places)", "Why people migrated (looking for food, water, safety)", "People settled in different parts of Nigeria", "The Nok people (very old civilization)", "They made beautiful clay pots", "They knew how to use iron", "Where people settled (near rivers, forests, grasslands)", "Activity: Simple map showing movement of people", "Creating clay models like Nok people"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,716) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-nigerian-history-t1-w8','ng-scheme-2025-preprimary-primary','P2','nigerian-history',1,'8',8,'teaching',null,'Major Ethnic Groups in Nigeria','["Nigeria has many ethnic groups", "Three major ethnic groups: Hausa-Fulani, Igbo, Yoruba", "Hausa-Fulani people (mostly in the North)", "Igbo people (mostly in the East)", "Yoruba people (mostly in the West)", "Other ethnic groups (Ijaw, Tiv, Kanuri, Ibibio, Edo, and many more)", "Over 250 ethnic groups in Nigeria", "Each group has its own language and culture", "Activity: Learning \"hello\" in different languages", "Discussion: Celebrating our diversity"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,716) on conflict (id) do nothing;
