insert into curriculum_topics values ('P2-nigerian-history-t2-w1','ng-scheme-2025-preprimary-primary','P2','nigerian-history',2,'1',1,'teaching',null,'Heroes and Heroines in Nigeria: What is a Hero/Heroine?','["Who is a hero or heroine?", "Someone who does something brave and good", "People who help their community", "People who fight for what is right", "Heroes can be men, heroines can be women", "Why we remember heroes and heroines", "They make our country proud", "We learn from their good examples", "Activity: Drawing \"My Hero\"", "Discussion: Who are heroes in our lives?"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,718) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-nigerian-history-t2-w2','ng-scheme-2025-preprimary-primary','P2','nigerian-history',2,'2',2,'teaching',null,'Heroes and Heroines in Nigeria: Queen Amina of Zazzau','["Who was Queen Amina?", "A brave Hausa warrior queen", "She lived in Zazzau (now Zaria) long ago", "She was a great fighter and leader", "She led her army to many victories", "She expanded her kingdom", "She built strong walls around cities", "Queen Amina was strong and fearless", "Activity: Drawing Queen Amina", "Story: Queen Amina''s brave deeds"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,718) on conflict (id) do nothing;
