insert into curriculum_topics values ('P2-nigerian-history-t2-w7','ng-scheme-2025-preprimary-primary','P2','nigerian-history',2,'7',7,'teaching',null,'Heroes and Heroines in Nigeria: Usman dan Fodio','["Who was Usman dan Fodio?", "A great Islamic scholar and leader", "He lived in Hausa land", "He was very learned and religious", "He started the Sokoto Caliphate", "He promoted education and Islam", "He wrote many books", "People respected his knowledge", "Activity: Drawing books to represent learning", "Discussion: Importance of education"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,719) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-nigerian-history-t2-w8','ng-scheme-2025-preprimary-primary','P2','nigerian-history',2,'8',8,'teaching',null,'Heroes and Heroines in Nigeria: Nana of Itsekiri','["Who was Nana?", "A powerful Itsekiri leader and trader", "He controlled trade in the Niger Delta", "He was very wealthy and influential", "He fought against British control", "He defended his people''s rights", "He was brave and strong", "Activity: Drawing trading activities", "Story: Nana''s resistance"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,719) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-nigerian-history-t2-w9','ng-scheme-2025-preprimary-primary','P2','nigerian-history',2,'9',9,'teaching',null,'Heroes and Heroines in Nigeria: Funmilayo Ransome-Kuti','["Who was Funmilayo Ransome-Kuti?", "A brave woman who fought for rights", "She fought for women''s rights", "She led protests against unfair taxes", "She wanted education for all girls", "She traveled to many countries", "She was fearless and strong", "Activity: Discussing fairness and rights", "Drawing women doing important work"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,719) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-nigerian-history-t2-w10','ng-scheme-2025-preprimary-primary','P2','nigerian-history',2,'10',10,'teaching',null,'Heroes and Heroines in Nigeria: Herbert Macaulay','["Who was Herbert Macaulay?", "Known as the \"Father of Nigerian Nationalism\"", "He fought for Nigerian people''s rights", "He spoke against unfair treatment", "He started the first political party in Nigeria", "He used newspapers to speak the truth", "He wanted Nigeria to be free", "Activity: Creating a simple newspaper page", "Discussion: Standing up for what is right"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,719) on conflict (id) do nothing;
