insert into curriculum_topics values ('P2-nigerian-history-t3-w1','ng-scheme-2025-preprimary-primary','P2','nigerian-history',3,'1',1,'teaching',null,'Political Developments: Colonial Period in Nigeria','["What does \"colonial\" mean?", "When another country rules your country", "The British came to Nigeria", "They came to trade at first", "Later they took control of Nigeria", "Nigeria became a British colony", "British ruled Nigeria for many years", "Nigerians were not happy being ruled", "Activity: Looking at old colonial pictures", "Discussion: How people felt"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,721) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-nigerian-history-t3-w2','ng-scheme-2025-preprimary-primary','P2','nigerian-history',3,'2',2,'teaching',null,'Political Developments: Nigerian Leaders Who Fought for Freedom','["Many Nigerians wanted freedom", "Leaders fought against British rule", "Dr. Nnamdi Azikiwe (Zik of Africa)", "Chief Obafemi Awolowo", "Sir Ahmadu Bello (Sardauna of Sokoto)", "Sir Abubakar Tafawa Balewa", "They asked for Nigeria''s independence", "They used words, not weapons", "Activity: Drawing our founding fathers", "Learning their names"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,721) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-nigerian-history-t3-w3','ng-scheme-2025-preprimary-primary','P2','nigerian-history',3,'3',3,'teaching',null,'Political Developments: Nigeria''s Independence','["What is independence?", "Being free to rule yourself", "Nigeria gained independence on October 1, 1960", "We celebrate Independence Day every year", "Princess Alexandra came from Britain", "The British flag was lowered", "The Nigerian flag was raised", "People celebrated with joy", "Nigeria became a free country", "Activity: Making Nigerian flags", "Singing the national anthem"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,721) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-nigerian-history-t3-w4','ng-scheme-2025-preprimary-primary','P2','nigerian-history',3,'4',4,'teaching',null,'Political Developments: First Leaders of Independent Nigeria','["Sir Abubakar Tafawa Balewa (first Prime Minister)", "Dr. Nnamdi Azikiwe (first President)", "They led the new Nigeria", "They worked to build the country", "Nigeria had many states", "People were proud to be Nigerian", "Challenges of a new nation", "Activity: Drawing our first leaders", "Creating independence day cards"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,721) on conflict (id) do nothing;
