insert into curriculum_topics values ('P2-nigerian-history-t3-w7','ng-scheme-2025-preprimary-primary','P2','nigerian-history',3,'7',7,'teaching',null,'Political Developments: Nigerian Symbols and Identity','["Our national flag (green-white-green)", "Green means agriculture and forests", "White means peace and unity", "Our national anthem", "Our national pledge", "Our coat of arms", "The eagle represents strength", "The black shield represents good soil", "These symbols unite all Nigerians", "Activity: Coloring national symbols", "Memorizing anthem and pledge"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,722) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-nigerian-history-t3-w8','ng-scheme-2025-preprimary-primary','P2','nigerian-history',3,'8',8,'teaching',null,'Political Developments: Unity in Nigeria','["Nigeria has many ethnic groups", "We speak different languages", "We have different cultures", "But we are all Nigerians", "Unity means being together", "Working together for progress", "Respecting all tribes and religions", "One Nigeria, one people", "Activity: Unity poster making", "Holding hands in unity circle"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,722) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-nigerian-history-t3-w9','ng-scheme-2025-preprimary-primary','P2','nigerian-history',3,'9',9,'teaching',null,'Political Developments: Important Places in Nigerian History','["Places where important things happened", "Independence House (Lagos) - where independence was declared", "Aso Rock (Abuja) - where our President lives", "National Museum (Lagos) - keeps historical items", "Old palaces and monuments", "These places remind us of our history", "We should protect historical places", "Activity: Looking at pictures of historical places", "Drawing our favorite historical place"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,722) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-nigerian-history-t3-w10','ng-scheme-2025-preprimary-primary','P2','nigerian-history',3,'10',10,'teaching',null,'Political Developments: Being a Good Nigerian Citizen','["We are all Nigerians", "Being proud of our country", "Respecting our flag and anthem", "Learning about our history", "Loving all Nigerians regardless of tribe", "Obeying our country''s laws", "Helping to make Nigeria better", "We are the future of Nigeria", "Activity: \"I am Nigerian\" presentation", "Pledging to be good citizens"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,722) on conflict (id) do nothing;
