insert into curriculum_topics values ('P2-social-and-citizenship-studies-t1-w1','ng-scheme-2025-preprimary-primary','P2','social-and-citizenship-studies',1,'1',1,'teaching',null,'Being a Good Citizen','["What does it mean to be a citizen?", "We are all citizens of Nigeria", "Being a good person in our community", "Understanding our rights: Right to learn, play, be safe, be treated fairly", "Understanding our responsibilities: Being kind, helping others, following rules, respecting everyone", "Making good choices every day", "Treating everyone fairly (social justice)", "Speaking up when something is wrong", "Taking care of our community", "Being proud to be Nigerian", "Activity: \"What makes a good citizen?\" class discussion", "Drawing: \"Me as a good citizen\""]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,724) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-social-and-citizenship-studies-t1-w2','ng-scheme-2025-preprimary-primary','P2','social-and-citizenship-studies',1,'2',2,'teaching',null,'Our Community','["What is a community?", "People living and working together", "Our community is part of who we are (identity)", "Types of communities: Urban (city/town) - busy, many buildings, markets", "Rural (village) - farms, quiet, close to nature", "How communities are different but connected", "Appreciating diversity in communities", "How different communities help each other", "Our role in making community better", "Community values: Sharing, helping, cooperating", "Social responsibility in our community", "Activity: Drawing and describing our community", "Discussion: What makes our community special?", "Sharing: Special things about our community"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,724) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-social-and-citizenship-studies-t1-w3','ng-scheme-2025-preprimary-primary','P2','social-and-citizenship-studies',1,'3',3,'teaching',null,'Leaders in our Community','["What is leadership?", "Leaders help guide and serve people", "Qualities of good leaders: Honest, kind, fair, brave, helpful, good listener", "Types of community leaders: Traditional leaders (Oba, Emir, Chief, Village Head)", "Religious leaders (Pastor, Imam)", "Community leaders (Baale, Chairman)", "School leaders (Head Teacher, Class Captain, Prefects)", "Family leaders (Parents, Grandparents)", "How leaders serve the community (civic responsibility)", "Respecting and supporting our leaders", "Everyone can be a leader in small ways", "Leadership skills for children: Speaking clearly, listening to others, being fair, helping solve problems", "Activity: Class leadership roles assignment", "Practice: Leading a group activity"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,724) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-social-and-citizenship-studies-t1-w4','ng-scheme-2025-preprimary-primary','P2','social-and-citizenship-studies',1,'4',4,'teaching',null,'Understanding Our World','["Learning about people and places", "Understanding ourselves and others", "Why we study about communities and cultures", "Learning about our environment", "Learning about families and relationships", "Understanding our country Nigeria", "Nigeria has many cultures and languages", "Learning about other countries too", "We are all part of the world (global citizenship)", "Appreciating differences and similarities", "Building social skills and values", "Critical thinking: Asking questions and finding answers", "Activity: Exploring different cultures through pictures", "Discussion: What we want to learn about the world"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,725) on conflict (id) do nothing;
