insert into curriculum_topics values ('P2-social-and-citizenship-studies-t1-w7','ng-scheme-2025-preprimary-primary','P2','social-and-citizenship-studies',1,'7',7,'teaching',null,'Our Physical Environment','["What is our physical environment?", "Everything around us we can see and touch", "Natural features: Mountains, rivers, trees, plants, animals", "Man-made features: Houses, roads, schools, bridges, markets", "How environment affects how we live", "People adapting to different environments", "Taking care of our environment (sustainability)", "Not destroying trees and plants", "Protecting animals and nature", "What is sustainability? Using resources wisely so they last", "Our actions affect the environment", "Being responsible environmental citizens", "Activity: Identifying natural and man-made things", "Project: Simple environment care plan for our class"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,725) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-social-and-citizenship-studies-t1-w8','ng-scheme-2025-preprimary-primary','P2','social-and-citizenship-studies',1,'8',8,'teaching',null,'Foods We Eat in our Culture','["What is culture? Our way of life and traditions", "Food is part of our cultural identity", "Nigerian foods we eat: Jollof rice, fried rice, beans, yam, plantain", "Soups: Egusi, okro, ogbono, efo riro, pepper soup", "Swallow foods: Eba, fufu, amala, tuwo, pounded yam", "Breakfast foods: Akara, moi-moi, pap, bread and tea", "Snacks: Chin-chin, puff-puff, plantain chips, groundnut", "Fruits: Orange, mango, banana, pawpaw, watermelon", "Different foods from Nigerian cultures (Yoruba, Igbo, Hausa, others)", "Appreciating cultural diversity through food", "Respecting others'' food choices and cultures", "Sharing meals brings people together", "Activity: Sharing our family''s special meals", "Discussion: How food connects us to our culture"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,726) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-social-and-citizenship-studies-t1-w9','ng-scheme-2025-preprimary-primary','P2','social-and-citizenship-studies',1,'9',9,'teaching',null,'Importance of Good Nutrition','["Why we need to eat good food", "Food gives us energy to learn and play", "Food helps us grow strong and healthy", "Types of food nutrients (simple): Body-building foods (protein) - fish, meat, eggs, beans", "Energy foods (carbohydrates) - rice, yam, bread, garri", "Protective foods (vitamins) - fruits and vegetables", "Making healthy food choices (decision-making)", "Eating balanced meals", "Drinking clean water for health", "Consequences of poor eating habits", "Global issue: Some children don''t have enough food", "Being grateful and not wasting food", "Social responsibility: Sharing with those who need", "Activity: Creating a balanced meal plate", "Sorting foods into nutrient groups"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,726) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-social-and-citizenship-studies-t1-w10','ng-scheme-2025-preprimary-primary','P2','social-and-citizenship-studies',1,'10',10,'teaching',null,'Greetings and Respect in our Culture','["Culture shapes how we interact with others", "Social values: Respect, courtesy, kindness", "Importance of greeting others", "Greetings show respect and build relationships", "Nigerian cultural greetings: Yoruba (prostrating for boys, kneeling for girls)", "Igbo (bowing slightly with respect)", "Hausa (handshake and bowing)", "Other ethnic greetings in Nigeria", "Using respectful words: \"Sir\", \"Ma\", \"Please\", \"Thank you\"", "Why respecting elders matters in our culture", "Interpersonal skills: Listening when others speak", "Helping elders and being obedient", "Appreciating cultural diversity in Nigeria", "Respecting different cultures and traditions", "Global citizenship: Respect is valued everywhere", "Activity: Practicing greetings from different cultures", "Role-play: Showing respect in various situations"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,726) on conflict (id) do nothing;
