insert into curriculum_topics values ('P2-social-and-citizenship-studies-t2-w1','ng-scheme-2025-preprimary-primary','P2','social-and-citizenship-studies',2,'1',1,'teaching',null,'Keeping our Environment Clean','["What is our environment?", "Home, school, and community surroundings", "Why environmental cleanliness matters", "Clean environment = healthy people", "Sustainability: Taking care so environment lasts", "Dirty environment causes diseases", "Our civic responsibility to keep environment clean", "Ways to maintain cleanliness: Using dustbins, sweeping, no littering", "Proper waste disposal", "Reducing waste (using less)", "Reusing items when possible", "Recycling materials", "Working together for clean community", "Leadership in environmental care", "Activity: Classroom cleaning project organization", "Creating recycling bins for class"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,728) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-social-and-citizenship-studies-t2-w2','ng-scheme-2025-preprimary-primary','P2','social-and-citizenship-studies',2,'2',2,'teaching',null,'Environmental Health and Protection','["How dirty environment affects health", "Diseases from unclean environment: Malaria, cholera, typhoid", "How diseases spread in dirty places", "Preventing diseases through cleanliness", "Community sanitation and cooperation", "Taking initiative in keeping things clean", "Making our environment beautiful", "Planting trees and flowers (sustainability)", "Protecting water sources from pollution", "Not throwing waste in drains and gutters", "Global environmental issues (simple): Pollution, too much waste", "Being responsible global citizens", "Social justice: Everyone deserves clean environment", "Activity: Environmental awareness poster making", "Project: \"Keep it Clean\" campaign planning"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,728) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-social-and-citizenship-studies-t2-w3','ng-scheme-2025-preprimary-primary','P2','social-and-citizenship-studies',2,'3',3,'teaching',null,'Safety at Home and School','["Understanding safety and why it matters", "What are accidents?", "Common accidents: Falls, burns, cuts, injuries", "Identifying dangerous situations (critical thinking)", "Accidents at home: Slippery floors, hot objects, sharp items, electricity", "Accidents at school: Playground injuries, running in class, fighting", "Causes of accidents: Carelessness, not following rules, not paying attention", "Personal responsibility in staying safe", "Making safe choices (decision-making skill)", "Being aware of surroundings (mindfulness)", "Looking out for others'' safety (empathy)", "Social responsibility: Warning others of danger", "Activity: Safety inspection in classroom", "Identifying potential hazards"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,728) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-social-and-citizenship-studies-t2-w4','ng-scheme-2025-preprimary-primary','P2','social-and-citizenship-studies',2,'4',4,'teaching',null,'Accident Prevention and Response','["How to prevent accidents (problem-solving)", "Safety rules at home: Walk don''t run, be careful with heat, keep sharp things away, don''t touch electrical outlets", "Safety rules at school: Follow teacher''s instructions, don''t push or fight, play carefully and safely", "Self-discipline in following safety rules", "Taking care of ourselves and others", "What to do when accidents happen: Stay calm (emotional control), call for help immediately, tell an adult, don''t move injured person", "Basic first aid awareness: Cleaning small cuts, applying bandages", "Communication skills in emergencies", "Being responsible and helpful in crisis", "Compassion for accident victims", "Activity: Creating classroom safety rules chart", "Practice: Emergency response role-play"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,729) on conflict (id) do nothing;
