insert into curriculum_topics values ('P2-social-and-citizenship-studies-t2-w7','ng-scheme-2025-preprimary-primary','P2','social-and-citizenship-studies',2,'7',7,'teaching',null,'Understanding Medicines','["What are medicines/drugs?", "Medicines help cure sickness and reduce pain", "Types of medicines: Tablets, syrups, injections, capsules", "Where medicines come from: Doctors, pharmacies, hospitals", "Who gives us medicines: Doctors, nurses, parents", "Common medicines children know: Paracetamol, cough syrup", "Proper use of medicines", "Following instructions carefully (discipline)", "Only adults should give children medicine", "Never taking medicine without permission", "Trusting medical professionals", "Decision-making: Asking when unsure", "Social responsibility: Not sharing medicines", "Activity: Identifying medicine containers safely", "Discussion: Why we need adult permission"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,729) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-social-and-citizenship-studies-t2-w8','ng-scheme-2025-preprimary-primary','P2','social-and-citizenship-studies',2,'8',8,'teaching',null,'Drug Abuse and Making Good Choices','["What is drug abuse?", "Using medicines wrongly or dangerously", "Taking medicine without permission", "Taking too much medicine", "Taking someone else''s medicine", "Understanding consequences (critical thinking)", "Why drug abuse is very dangerous: Serious sickness, poisoning, death", "Peer pressure: When friends ask you to do wrong things", "Emotional intelligence: Recognizing dangerous situations", "Self-control and making good choices", "Assertiveness: Saying \"No\" confidently", "Being brave to refuse wrong things", "Reporting concerning behavior to adults", "Social responsibility: Helping friends make good choices", "Activity: \"Just Say No\" practice scenarios", "Building confidence in refusing"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,730) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-social-and-citizenship-studies-t2-w9','ng-scheme-2025-preprimary-primary','P2','social-and-citizenship-studies',2,'9',9,'teaching',null,'Identifying Harmful Substances','["What are harmful substances?", "Dangerous things that can hurt or kill us", "Types of harmful substances: Poisons (rat poison, insecticides), Cleaning products (bleach, detergent)", "Chemicals (kerosene, petrol, spirits)", "Unknown plants and berries", "Expired or spoiled food and drinks", "Understanding dangers (risk awareness)", "Why accidents happen with harmful substances", "Critical thinking: Identifying dangerous items", "Warning labels and danger symbols", "Skull and crossbones means poison", "Consequences of taking harmful substances", "Personal responsibility in safety", "Being cautious and careful", "Activity: Identifying warning symbols on products", "Creating safety warning posters"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,730) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-social-and-citizenship-studies-t2-w10','ng-scheme-2025-preprimary-primary','P2','social-and-citizenship-studies',2,'10',10,'teaching',null,'Avoiding Harmful Substances','["How to avoid harmful substances (decision-making)", "Never eat or drink anything unknown", "Always ask an adult first", "Don''t smell, taste, or touch chemicals", "Stay away from cleaning products", "Don''t pick and eat unknown berries or plants", "Wash fruits and vegetables before eating", "Check food expiry dates with adults", "Drink only clean, safe water", "What to do if you swallow harmful substance: Tell adult immediately (don''t hide it), Go to hospital quickly, Stay calm", "Communication skills in emergencies", "Courage to speak up when scared", "Social responsibility: Helping siblings stay safe", "Leadership: Teaching younger children safety", "Activity: Safety rules poster competition", "Role-play: Responding to dangerous situations"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,730) on conflict (id) do nothing;
