insert into curriculum_topics values ('P2-social-and-citizenship-studies-t3-w1','ng-scheme-2025-preprimary-primary','P2','social-and-citizenship-studies',3,'1',1,'teaching',null,'Understanding Danger and Security','["What is security? Being safe and protected", "What is danger? Things that can harm us", "What is insecurity? When we are not safe", "Understanding personal safety (critical thinking)", "Sources of danger at home: Fire, electricity, sharp objects, hot things, strangers", "Sources of danger at school: Bullies, broken equipment, unsafe play areas", "Sources of danger in community: Bad roads, open gutters, fast vehicles, crime", "Natural dangers: Floods, storms, lightning", "Emotional intelligence: Recognizing when you feel unsafe", "Trusting your instincts about danger", "Civic responsibility: Reporting dangers to adults", "Activity: Creating a danger awareness map", "Discussion: What makes us feel safe or unsafe?"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,732) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-social-and-citizenship-studies-t3-w2','ng-scheme-2025-preprimary-primary','P2','social-and-citizenship-studies',3,'2',2,'teaching',null,'Personal Safety Strategies','["How to stay safe (problem-solving skills)", "Fire safety: Don''t play with matches, know exit routes, \"stop-drop-roll\" if clothes catch fire", "Electrical safety: Don''t touch outlets, keep away from wires", "Stranger danger awareness: Never follow strangers, Don''t accept gifts from strangers, Don''t enter stranger''s car or house, Scream \"Help!\" and run if approached", "Road safety: Look left-right-left before crossing, Use zebra crossings, Don''t play on the road", "Dealing with bullies (conflict resolution): Tell a teacher or parent, Don''t fight back, Stay with friends, Walk away calmly", "Emotional intelligence: Managing fear appropriately", "Assertiveness: Speaking up for yourself", "Decision-making under pressure", "Knowing important information: Full name, parents'' phone numbers, home address", "Activity: Safety scenario practice", "Role-play: What to do in emergencies"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,732) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-social-and-citizenship-studies-t3-w3','ng-scheme-2025-preprimary-primary','P2','social-and-citizenship-studies',3,'3',3,'teaching',null,'People Who Protect Us - Police','["Understanding security agencies", "People whose job is to keep us safe", "Why we need people to protect us", "The Nigeria Police Force", "Police uniform: Black or blue", "What police do: Catch criminals and thieves, Protect people and property, Control traffic and maintain order, Help people in danger and emergencies", "Police maintain law and order", "Police stations in our community", "Police emergency numbers: 112, 767", "When to call the police", "Social values: Respecting police officers", "Civic responsibility: Cooperating with police", "Obeying laws and rules", "Being honest with police", "Activity: Drawing police officers at work", "Discussion: How police help our community"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,732) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-social-and-citizenship-studies-t3-w4','ng-scheme-2025-preprimary-primary','P2','social-and-citizenship-studies',3,'4',4,'teaching',null,'People Who Protect Us - Armed Forces','["Nigerian Army: Uniform (camouflage - green and brown)", "Army duties: Protect our country from enemies, Defend Nigeria''s borders, Fight wars if needed, Help during emergencies and disasters", "Nigerian Navy: Uniform (white)", "Navy duties: Protect our seas and rivers, Stop pirates and criminals on water, Patrol coastlines", "Nigerian Air Force: Uniform (blue-grey)", "Air Force duties: Protect our skies, Fly military planes, Watch over Nigeria from the air", "Understanding national security", "Why protecting our country matters", "Courage and sacrifice of military personnel", "Appreciating those who serve (gratitude)", "National pride and patriotism", "Social justice: Everyone deserves to be safe", "Activity: Matching uniforms to agencies", "Discussion: Why people serve their country"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,733) on conflict (id) do nothing;
