insert into curriculum_topics values ('P2-social-and-citizenship-studies-t3-w7','ng-scheme-2025-preprimary-primary','P2','social-and-citizenship-studies',3,'7',7,'teaching',null,'People Who Protect Us - Safety Services','["Nigerian Civil Defence Corps (NSCDC): Uniform (green), Duties: Protect government buildings, Help during disasters, Protect important facilities", "Federal Road Safety Corps (FRSC): Uniform (white and green), Duties: Keep roads safe, Control traffic on highways, Check vehicles for safety, Help accident victims, Teach road safety", "Our responsibility as road users", "Following traffic rules as pedestrians", "Being careful on the road", "Civic duty in promoting safety", "Cooperation with safety officials", "Respect for authority and rules", "Understanding rules protect everyone", "Activity: Road safety role-play", "Creating road safety awareness materials"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,733) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-social-and-citizenship-studies-t3-w8','ng-scheme-2025-preprimary-primary','P2','social-and-citizenship-studies',3,'8',8,'teaching',null,'People Who Protect Us - Emergency Services','["Fire Service: Uniform (yellow or red), Duties: Put out fires, Rescue people from burning buildings, Teach fire safety, Respond to disasters", "Fire safety education", "What to do if there''s a fire: Get out quickly, Call for help, Don''t go back inside", "Ambulance/Emergency Medical Services: Help sick and injured people, Take people to hospital quickly, Provide emergency medical care", "Importance of emergency response", "How to call for help: Stay calm, Speak clearly, Give correct location, Explain the emergency", "Working together in emergencies (teamwork)", "Social responsibility in emergencies", "Compassion for people in danger", "Activity: Mock emergency call practice", "Discussion: How we can help during emergencies"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,734) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-social-and-citizenship-studies-t3-w9','ng-scheme-2025-preprimary-primary','P2','social-and-citizenship-studies',3,'9',9,'teaching',null,'Understanding Money','["What is money?", "Money is what we use to buy things", "Nigerian currency: Naira (₦) and Kobo", "Nigerian coins: 50 kobo, ₦1, ₦2", "Nigerian notes: ₦5, ₦10, ₦20, ₦50, ₦100, ₦200, ₦500, ₦1000", "Why we need money: To buy food, clothes, pay for school, buy things we need", "Where money comes from: Parents work to earn money", "Different jobs people do to earn money", "Simple buying and selling: Going to the market, paying for items, receiving change", "Being careful with money", "Not wasting money on unnecessary things", "Saving money for future needs", "Financial responsibility (life skill)", "Activity: Identifying Nigerian currency", "Simple money counting games", "Role-play: Buying and selling in a pretend shop"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,734) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-social-and-citizenship-studies-t3-w10','ng-scheme-2025-preprimary-primary','P2','social-and-citizenship-studies',3,'10',10,'teaching',null,'Using Money Wisely','["Making smart choices with money (decision-making)", "Needs vs. wants: Things we need (food, clothes, books), Things we want (toys, sweets)", "Prioritizing needs over wants", "Saving money in a piggy bank or savings box", "Why saving is important: For emergencies, For future goals, To buy important things later", "Not begging for everything we see", "Being grateful for what we have", "Sharing and giving to those in need (charity)", "Introduction to digital money (simple): Some people use cards or phones to pay, Money can be kept in banks", "Banks keep money safe", "Financial literacy as life skill", "Social responsibility with money", "Global citizenship: Using resources wisely", "Activity: Creating a simple savings goal", "Making a \"needs and wants\" chart", "Discussion: How to be responsible with money"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,735) on conflict (id) do nothing;
