insert into curriculum_topics values ('P4-english-language-t1-w1','ng-scheme-2025-preprimary-primary','P4','english-language',1,'1',1,'teaching',null,'Conversations/Dialogues Using Modal Auxiliaries (Part 1)','[" Meaning and uses of modal auxiliaries  Modal auxiliaries: can/could (ability, permission, possibility)  Examples: \"I can swim\", \"Could you help me?\"  Modal auxiliaries: will/would (future actions, polite requests)  Examples: \"I will come tomorrow\", \"Would you like some water?\"  Practice dialogues using can/could and will/would"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,771) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-english-language-t1-w2','ng-scheme-2025-preprimary-primary','P4','english-language',1,'2',2,'teaching',null,'Conversations/Dialogues Using Modal Auxiliaries (Part 2)','[" Modal auxiliaries: shall/should (suggestions, obligations, advice)  Examples: \"Shall we go?\", \"You should study hard\"  Modal auxiliaries: may/might (permission, possibility)  Examples: \"May I go out?\", \"It might rain today\"  Observing conversation etiquette: turn-taking, listening, politeness  Practice dialogues using shall/should and may/might"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,771) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-english-language-t1-w3','ng-scheme-2025-preprimary-primary','P4','english-language',1,'3',3,'teaching',null,'Conversations/Dialogues Using Modal Auxiliaries (Part 3)','[" Modal auxiliaries: must, ought to (strong obligation, necessity)  Examples: \"You must obey your parents\", \"We ought to be grateful\"  Modal auxiliaries: need to, used to, dare  Examples: \"I need to finish my homework\", \"I used to live in Lagos\", \"How dare you!\"  Engaging in conversations on national values using modal auxiliaries  Group dialogues and role-play activities"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,771) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-english-language-t1-w4','ng-scheme-2025-preprimary-primary','P4','english-language',1,'4',4,'teaching',null,'Conversations/Dialogues Using Modal Auxiliaries (Part 4)','[" Creating conversations on various topics using modal auxiliaries:  Insecurity: \"We should report suspicious activities\"  Financial system: \"We must save money for the future\"  Corruption: \"Leaders ought to be honest\"  Observing conversation etiquette in group discussions  Class debates using modal auxiliaries  Assessment of modal auxiliary usage"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,771) on conflict (id) do nothing;
