insert into curriculum_topics values ('P4-english-language-t1-w7','ng-scheme-2025-preprimary-primary','P4','english-language',1,'7',7,'teaching',null,'Aural Discrimination in Vowels','[" Discriminating between the sounds /˄/ and /3:/ in words  Practice words:  cup/curb, luck/lurk, gull/girl, bust/burst  Listening exercises to identify sounds  Pronunciation practice  Using words in sentences  Spelling activities with these sound patterns"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,772) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-english-language-t1-w8','ng-scheme-2025-preprimary-primary','P4','english-language',1,'8',8,'teaching',null,'Aural Discrimination in Consonants','[" Discriminating between pairs of consonants /ʧ/ and /ʃ/  Practice words: chin/shin, chop/shop, catch/cash  Discriminating between /v/ and /f/  Practice words: vest/first, very/ferry, have/half  Distinguishing between voiced and voiceless consonant sounds  Pronunciation drills and listening activities"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,772) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-english-language-t1-w9','ng-scheme-2025-preprimary-primary','P4','english-language',1,'9',9,'teaching',null,'Homophones and Homographs (Part 1)','[" Understanding homophones: words that sound the same but have different meanings  Examples and practice:  to/too/two, their/there/they''re  bare/bear, fair/fare, knight/night  Using homophones correctly in sentences  Spelling practice with homophones  Context clues to determine correct homophone"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,772) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-english-language-t1-w10','ng-scheme-2025-preprimary-primary','P4','english-language',1,'10',10,'teaching',null,'Homophones and Homographs (Part 2)','[" Understanding homographs: words with same spelling but different meanings  Examples and practice:  bank (financial institution) / bank (riverbank)  bat (animal) / bat (sports equipment)  spring (season) / spring (coiled metal object)  Using context to understand homograph meanings  Creating sentences with homographs  Homophone and homograph games and exercises"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,772) on conflict (id) do nothing;
