insert into curriculum_topics values ('P4-english-language-t2-w1','ng-scheme-2025-preprimary-primary','P4','english-language',2,'1',1,'teaching',null,'Using Past, Present and Future Tenses','[" Understanding the three main tenses  Past tense: actions that already happened  Examples: \"I ate yesterday\", \"She went to school\"  Present tense: actions happening now or regularly  Examples: \"I eat rice everyday\", \"He plays football\"  Future tense: actions that will happen  Examples: \"I will eat salad tomorrow\", \"We shall visit grandma\"  Practice: Converting sentences between tenses"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,774) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-english-language-t2-w2','ng-scheme-2025-preprimary-primary','P4','english-language',2,'2',2,'teaching',null,'Nouns and Pronouns','[" Identification of nouns: naming words (people, places, things, ideas)  Types of nouns: common, proper, collective, abstract  Understanding pronouns: words that replace nouns  Types of pronouns: personal (I, you, he, she, it, we, they), possessive (mine, yours, his, hers, ours, theirs)  Use of nouns and pronouns in sentences  Agreement between nouns and pronouns"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,774) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-english-language-t2-w3','ng-scheme-2025-preprimary-primary','P4','english-language',2,'3',3,'teaching',null,'Adjectives and Adverbs (Part 1)','[" Meaning of adjectives: words that describe nouns  Types of adjectives:  Quantitative adjectives (describe quantity): many, few, some  Qualitative adjectives (describe quality): beautiful, tall, kind  Demonstrative adjectives: this, that, these, those  Interrogative adjectives: which, what, whose  Possessive adjectives: my, your, his, her, our, their  Using adjectives to enhance descriptions"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,774) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-english-language-t2-w4','ng-scheme-2025-preprimary-primary','P4','english-language',2,'4',4,'teaching',null,'Adjectives and Adverbs (Part 2)','[" Comparative forms of adjectives  Examples: \"Janelle is taller than her friend\", \"Bimpe is more intelligent than Ola\"  Order of adjectives: opinion-size-age-shape-color-origin-material-purpose  Meaning of adverbs: words that describe verbs, adjectives, or other adverbs  Types of adverbs: manner, time, place, frequency, degree  Comparative forms of adverbs: \"Ahmed walks more slowly than Eze\"  Use of adjectives and adverbs in sentences"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,774) on conflict (id) do nothing;
