insert into curriculum_topics values ('P4-english-language-t2-w7','ng-scheme-2025-preprimary-primary','P4','english-language',2,'7',7,'teaching',null,'Vocabulary: Common Idioms','[" Understanding idioms: expressions with meanings different from literal words  Common idioms and their meanings:  \"A piece of cake\" (very easy)  \"Break a leg\" (good luck)  \"Hit the nail on the head\" (exactly right)  \"Cost an arm and a leg\" (very expensive)  \"Once in a blue moon\" (very rarely)  Using idioms in sentences  Creating dialogues with idioms"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,775) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-english-language-t2-w8','ng-scheme-2025-preprimary-primary','P4','english-language',2,'8',8,'teaching',null,'Sense Relations: Synonyms and Antonyms','[" Meaning of synonyms: words with similar meanings  Examples: happy/joyful, big/large, smart/intelligent, begin/start  Using synonyms to improve vocabulary  Meaning of antonyms: words with opposite meanings  Examples: hot/cold, happy/sad, big/small, fast/slow  Using synonyms and antonyms in sentences  Word games with synonyms and antonyms"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,775) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-english-language-t2-w9','ng-scheme-2025-preprimary-primary','P4','english-language',2,'9',9,'teaching',null,'Sense Relations: Homonyms and Hyponyms','[" Meaning of homonyms: words that sound alike or are spelled alike but have different meanings  Examples: bank, bat, spring (as covered in homographs/homophones)  Meaning of hyponyms: specific words under a general category  Examples: Rose, lily, tulip are hyponyms of \"flower\"  Cat, dog, cow are hyponyms of \"animal\"  Using sense relations to expand vocabulary  Classification exercises"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,775) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-english-language-t2-w10','ng-scheme-2025-preprimary-primary','P4','english-language',2,'10',10,'teaching',null,'Vocabulary Associated with Various Fields (Part 1)','[" Family vocabulary: nuclear family, extended family, father, mother, sister, brothers, nieces, nephews, cousins, grandfather, grandmother, mother-in-law, step-mother, etc.  School vocabulary: uniform, library, lessons, exams, school bag, playground, assembly, sports, writing, etc.  Sports vocabulary: team, coach, player, goal, score, win, brace, lose, draw, game, referee, kick, etc.  Using context-specific vocabulary in sentences"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,776) on conflict (id) do nothing;
