insert into curriculum_topics values ('P4-english-language-t3-w1','ng-scheme-2025-preprimary-primary','P4','english-language',3,'1',1,'teaching',null,'Introduction to Stress','[" Meaning of stress: emphasis placed on syllables or words  Types of stress: Word stress: emphasis on specific syllables (e.g., TAble, WRIting, BEAutiful)  Sentence stress: emphasis on certain words for meaning (e.g., \"I DIDN''T say he stole it\" vs. \"I didn''t say HE stole it\")  Simple stress placement rules for two-syllable words  Practice identifying and marking stressed syllables"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,777) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-english-language-t3-w2','ng-scheme-2025-preprimary-primary','P4','english-language',3,'2',2,'teaching',null,'Introduction to Stress (Continued)','[" Stress placement rules:  Two-syllable nouns/adjectives: stress first syllable (TAble, HAPpy)  Two-syllable verbs/prepositions: stress second syllable (arRIVE, beGIN)  Compound words: stress patterns (BLACKboard for nouns, overCOME for verbs)  Practice exercises with word and sentence stress  Pronunciation drills emphasizing correct stress"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,777) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-english-language-t3-w3','ng-scheme-2025-preprimary-primary','P4','english-language',3,'3',3,'teaching',null,'Introduction to Intonation','[" Meaning of intonation: rise and fall of voice in speaking  Importance of intonation:  Expresses attitudes and emotions  Differentiates questions from statements  Clarifies meaning in sentences  Types of intonation: rising intonation and falling intonation  Practice: \"You''re coming.\" (statement) vs. \"You''re coming?\" (question)"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,777) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-english-language-t3-w4','ng-scheme-2025-preprimary-primary','P4','english-language',3,'4',4,'teaching',null,'Dialogue Using Tag Questions','[" Meaning of question tags: short questions at the end of statements  Basic rules: positive statement → negative tag  negative statement → positive tag  Positive examples: \"Tomorrow is Monday, isn''t it?\", \"You are a boy/girl, aren''t you?\", \"She is quite attractive, isn''t she?\"  Negative examples: \"You didn''t come to school, did you?\", \"This book isn''t yours, is it?\"  Creating dialogues with tag questions  Practice conversations"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,777) on conflict (id) do nothing;
