insert into curriculum_topics values ('P4-english-language-t3-w7','ng-scheme-2025-preprimary-primary','P4','english-language',3,'7',7,'teaching',null,'Oral Composition: Narrative Composition','[" Narration on various topics:  \"A Visit to My Village\"  \"My First Day at School\"  \"A Visit to the Market\"  Elements of narrative: beginning, middle, end  characters, setting, events  Practice oral storytelling  Group narration activities  Recording or presenting narratives to class"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,778) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-english-language-t3-w8','ng-scheme-2025-preprimary-primary','P4','english-language',3,'8',8,'teaching',null,'Oral Composition: Descriptive Composition','[" Description of places, people, events  Using descriptive words: adjectives, sensory details  Practice describing:  A person (appearance, personality)  A place (school, market, village)  An event (birthday party, festival)  Oral presentations of descriptions  Peer feedback and improvement"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,778) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-english-language-t3-w9','ng-scheme-2025-preprimary-primary','P4','english-language',3,'9',9,'teaching',null,'Reading Comprehension: Using Contextual Clues','[" Reading passages on various issues:  Taxation, achieving academic excellence  Skill acquisition, building good character/manners  Using contextual clues to get meanings of unfamiliar words  Literal, inferential, and critical questions on passages  Using unfamiliar words in sentences  Vocabulary building through context"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,778) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-english-language-t3-w10','ng-scheme-2025-preprimary-primary','P4','english-language',3,'10',10,'teaching',null,'Reading Comprehension: Main and Supporting Ideas','[" Reading class-appropriate informational texts on:  Diet and nutrition, benefits of eating for healthy living  Pollution: types, causes, and purification  Charitable donations: importance of giving money to those in need  Identifying main ideas (what the passage is mostly about)  Identifying supporting ideas (details that support the main idea)  Practice summarizing passages"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,778) on conflict (id) do nothing;
