insert into curriculum_topics values ('P4-mathematics-t1-w1','ng-scheme-2025-preprimary-primary','P4','mathematics',1,'1',1,'teaching',null,'Whole Numbers (Part 1)','[" Counting and writing numbers 1-1,000  Place value: ones, tens, hundreds, thousands  Reading and writing numbers in words and figures  Expanded notation: 345 = 300 + 40 + 5  Comparing numbers using >, <, = symbols  Ordering numbers in ascending and descending order"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,780) on conflict (id) do nothing;
