insert into curriculum_topics values ('P4-mathematics-t1-w4','ng-scheme-2025-preprimary-primary','P4','mathematics',1,'4',4,'teaching',null,'Fractions (Part 1)','[" Understanding fractions: parts of a whole  Identifying and naming fractions: 1/2, 1/3, 1/4, 1/5, 1/8, 1/10  Numerator and denominator  Representing fractions using shapes and diagrams  Equivalent fractions: 1/2 = 2/4 = 3/6  Comparing fractions with same denominator"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,780) on conflict (id) do nothing;
