insert into curriculum_topics values ('P4-mathematics-t2-w2','ng-scheme-2025-preprimary-primary','P4','mathematics',2,'2',2,'teaching',null,'Division (Part 1)','[" Understanding division as sharing and grouping  Division as inverse of multiplication  Division facts from multiplication tables  Division of 2-digit numbers by 1-digit numbers (no remainder)  Division with remainders  Recording division: 15 ÷ 3 = 5 and 3)15"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,782) on conflict (id) do nothing;
