insert into curriculum_topics values ('P4-mathematics-t2-w7','ng-scheme-2025-preprimary-primary','P4','mathematics',2,'7',7,'teaching',null,'Open Sentences','[" Understanding open sentences (equations with missing numbers)  Finding missing numbers in addition: +5 = 12  Finding missing numbers in subtraction: 15 - =8  Finding missing numbers in multiplication: 4 × = 20  Finding missing numbers in division: ÷ 3= 7  Using trial and error and inverse operations  Creating and solving open sentences"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,782) on conflict (id) do nothing;
