insert into curriculum_topics values ('P4-physical-and-health-education-t1-w7','ng-scheme-2025-preprimary-primary','P4','physical-and-health-education',1,'7',7,'teaching',null,'Personal Health - Part 1','[" What is personal health?  Taking a bath every day  Washing hands with soap and water  When to wash hands: before eating, after toilet  Brushing teeth in the morning and at night  Cutting and cleaning fingernails  Combing hair every day"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,790) on conflict (id) do nothing;
