insert into curriculum_topics values ('P4-physical-and-health-education-t1-w9','ng-scheme-2025-preprimary-primary','P4','physical-and-health-education',1,'9',9,'teaching',null,'Personal Health - Part 3','[" Eating good food to stay healthy  Foods that help us grow: rice, yam, bread, beans  Foods that make us strong: meat, fish, eggs, milk  Eating fruits like oranges, bananas, apples  Eating vegetables like carrots, tomatoes  Drinking clean water every day  Not eating too much sugar and sweets"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,791) on conflict (id) do nothing;
