insert into curriculum_topics values ('P4-physical-and-health-education-t2-w1','ng-scheme-2025-preprimary-primary','P4','physical-and-health-education',2,'1',1,'teaching',null,'Relay Races - Part 1','[" What is a relay race?  Running as a team (4 people)  The baton (stick we pass)  Holding the baton properly  Simple relay games without baton  Running and tagging your friend  Waiting for your turn"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,792) on conflict (id) do nothing;
