insert into curriculum_topics values ('P4-physical-and-health-education-t2-w8','ng-scheme-2025-preprimary-primary','P4','physical-and-health-education',2,'8',8,'teaching',null,'Long Jump - Part 2','[" Practicing the run-up  Counting steps before jumping  Swinging arms when jumping  Lifting knees high in the air  Landing without falling backward  Measuring how far we jumped  Trying to jump farther each time  Safety rules in long jump"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,793) on conflict (id) do nothing;
