insert into curriculum_topics values ('P4-physical-and-health-education-t3-w1','ng-scheme-2025-preprimary-primary','P4','physical-and-health-education',3,'1',1,'teaching',null,'Tennis','[" What is tennis?  The tennis racket and ball  Holding the racket properly  Hitting the ball with the racket  Simple forehand hit (hitting from the side)  Bouncing the ball with the racket  Hitting the ball to a partner  Simple tennis games  Taking turns and playing fair"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,794) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-physical-and-health-education-t3-w2','ng-scheme-2025-preprimary-primary','P4','physical-and-health-education',3,'2',2,'teaching',null,'Table Tennis','[" What is table tennis (ping pong)?  The small table, net, and paddle  The small white ball  Holding the paddle correctly  Hitting the ball gently  Bouncing the ball on the paddle  Hitting ball back and forth over net  Simple table tennis games  Scoring points (basic)"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,794) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-physical-and-health-education-t3-w3','ng-scheme-2025-preprimary-primary','P4','physical-and-health-education',3,'3',3,'teaching',null,'Soccer - Part 1','[" What is soccer (football)?  The soccer ball and goal posts  Kicking the ball with our feet  Dribbling (moving with the ball)  Passing the ball to friends  Simple kicking games  Not using our hands (except goalkeeper)  Playing as a team"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,794) on conflict (id) do nothing;
