insert into curriculum_topics values ('P4-physical-and-health-education-t3-w7','ng-scheme-2025-preprimary-primary','P4','physical-and-health-education',3,'7',7,'teaching',null,'Basketball','[" What is basketball?  The basketball and hoop  Bouncing the ball (dribbling)  Catching and throwing the ball  Throwing ball into the basket  Using both hands to catch  Simple passing games  Not running with the ball without bouncing  Taking turns shooting"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,795) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-physical-and-health-education-t3-w8','ng-scheme-2025-preprimary-primary','P4','physical-and-health-education',3,'8',8,'teaching',null,'Volleyball','[" What is volleyball?  The volleyball and high net  Hitting the ball over the net  Using our hands to hit ball up  Simple underhand serve  Hitting ball to teammates  Working together to keep ball in the air  Not catching or holding the ball  Simple rotation games"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,795) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-physical-and-health-education-t3-w9','ng-scheme-2025-preprimary-primary','P4','physical-and-health-education',3,'9',9,'teaching',null,'First Aid and Safety Education','[" What is first aid?  Getting help when someone is hurt  Calling a teacher or adult  Simple cuts and bruises  Cleaning small cuts with water  Putting a plaster on cuts  What to do when someone falls  Ice for bumps and swelling  Not touching blood without adult help  When to get help immediately"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,795) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-physical-and-health-education-t3-w10','ng-scheme-2025-preprimary-primary','P4','physical-and-health-education',3,'10',10,'teaching',null,'Safety Precautions in Games and Sports','[" Warming up before playing (stretching and jogging)  Wearing the right clothes and shoes for sports  Drinking water when thirsty  Playing carefully to avoid hurting others  Following the rules of the game  Stopping when we are hurt or very tired  Playing in safe areas only  Listening to the teacher or coach  Cooling down after playing"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,795) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-physical-and-health-education-t3-w11','ng-scheme-2025-preprimary-primary','P4','physical-and-health-education',3,'11',11,'teaching',null,'Recreation and Leisure / Drug and Alcohol Education','[" Recreation and Leisure:  Having fun and relaxing  Playing games after school  Indoor games: cards, board games, drawing  Outdoor activities: playing in the park, riding bicycle  Hobbies: reading, singing, dancing  Resting and having fun is important  Drug and Alcohol Education:  Medicine helps when we are sick  Only take medicine from parents or doctor  Never take medicine alone  Some things are harmful: cigarettes, alcohol, drugs  Saying NO to strangers offering things  Telling parents or teachers if someone offers us something bad  Our body is important and we must keep it healthy"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,796) on conflict (id) do nothing;
