insert into curriculum_topics values ('P4-christian-religious-studies-t1-w1','ng-scheme-2025-preprimary-primary','P4','christian-religious-studies',1,'1',1,'teaching',null,'God Speaks to Us','[" Introduction: How does God speak to us?  God speaks through the Bible (His Word)  God speaks through parents and teachers  God speaks through pastors and church leaders  God speaks through our conscience (inner voice)  God speaks through prayer  Listening to God''s voice  Bible story: God speaks to Samuel (1 Samuel 3:1-10)"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,797) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-christian-religious-studies-t1-w2','ng-scheme-2025-preprimary-primary','P4','christian-religious-studies',1,'2',2,'teaching',null,'We are Children of One Father','[" God is our Heavenly Father  We are all God''s children  God created all people  We are brothers and sisters in Christ  Loving one another as God''s children  Respecting all people regardless of tribe or color  Living as one family in God  Bible verses: John 1:12, 1 John 3:1"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,797) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-christian-religious-studies-t1-w3','ng-scheme-2025-preprimary-primary','P4','christian-religious-studies',1,'3',3,'teaching',null,'God Calls Us for a Purpose','[" What does it mean to be called by God?  God has a special plan for everyone  God created us for a purpose  Using our talents and gifts for God  Obeying God''s call  Being helpful at home, school, and church  Bible stories: God calls Moses (Exodus 3:1-12)  God calls young Samuel (1 Samuel 3:1-10)"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,797) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-christian-religious-studies-t1-w4','ng-scheme-2025-preprimary-primary','P4','christian-religious-studies',1,'4',4,'teaching',null,'God Gives His Law to Us - Part 1','[" Introduction to God''s law  Why God gave us laws (to guide and protect us)  The Ten Commandments introduction  Where God gave the law (Mount Sinai to Moses)  The first commandment: No other gods  The second commandment: No idols  The third commandment: Respect God''s name  Bible reference: Exodus 20:1-17"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,797) on conflict (id) do nothing;
