insert into curriculum_topics values ('P4-christian-religious-studies-t1-w7','ng-scheme-2025-preprimary-primary','P4','christian-religious-studies',1,'7',7,'teaching',null,'God Gives His Law to Us - Part 2','[" The fourth commandment: Keep the Sabbath holy  The fifth commandment: Honor your parents  The sixth commandment: Do not kill  The seventh commandment: Be faithful in marriage  The eighth commandment: Do not steal  The ninth commandment: Do not lie  The tenth commandment: Do not covet  Why we should obey God''s commandments"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,798) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-christian-religious-studies-t1-w8','ng-scheme-2025-preprimary-primary','P4','christian-religious-studies',1,'8',8,'teaching',null,'God Reveals Himself to Us - Part 1','[" What does \"reveal\" mean? (God shows Himself)  God reveals Himself through creation (nature)  Looking at the sky, trees, animals - we see God''s work  God reveals Himself through His power  God reveals Himself through miracles  Bible stories: Creation (Genesis 1-2)  God appears to Moses in burning bush (Exodus 3)"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,798) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-christian-religious-studies-t1-w9','ng-scheme-2025-preprimary-primary','P4','christian-religious-studies',1,'9',9,'teaching',null,'God Reveals Himself to Us - Part 2','[" God reveals Himself through Jesus Christ  Jesus shows us what God is like  God reveals Himself through the Bible  God reveals Himself through the Holy Spirit  God reveals His love, mercy, and kindness  How we can know God better  Bible verse: John 14:9, Hebrews 1:1-2"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,798) on conflict (id) do nothing;
