insert into curriculum_topics values ('P4-christian-religious-studies-t2-w1','ng-scheme-2025-preprimary-primary','P4','christian-religious-studies',2,'1',1,'teaching',null,'Jesus'' Power to Forgive Sins','[" What is sin? (Disobeying God)  Everyone has sinned (Romans 3:23)  Jesus has power to forgive our sins  The story of the paralyzed man (Mark 2:1-12)  Jesus forgives the woman caught in sin (John 8:1-11)  How to receive forgiveness: confess and repent  Forgiving others as Jesus forgives us  Bible verse: 1 John 1:9"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,800) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-christian-religious-studies-t2-w2','ng-scheme-2025-preprimary-primary','P4','christian-religious-studies',2,'2',2,'teaching',null,'Jesus Loves All People - Part 1','[" Jesus loves everyone - no exceptions  Jesus loves children (Mark 10:13-16)  Jesus loves the poor and the rich  Jesus loves the sick and the healthy  Jesus and the Samaritan woman (John 4:1-42)  Jesus loves people others reject  Jesus calls tax collector Zacchaeus (Luke 19:1-10)"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,800) on conflict (id) do nothing;
