insert into curriculum_topics values ('P4-christian-religious-studies-t3-w1','ng-scheme-2025-preprimary-primary','P4','christian-religious-studies',3,'1',1,'teaching',null,'Jesus Gives Us a New Life - Part 2','[" What is the \"new life\" in Christ?  Being born again spiritually  Old things pass away, all things become new (2 Corinthians 5:17)  Living differently as Christians  Turning away from sin  Following Jesus'' example  Growing in faith and love  Bible verse: John 3:3, Romans 6:4"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,803) on conflict (id) do nothing;
