insert into curriculum_topics values ('P4-islamic-studies-t2-w4','ng-scheme-2025-preprimary-primary','P4','islamic-studies',2,'4',4,'teaching',null,'Sawm (Fasting) - Part 1','[" Introduction to fasting (Sawm)  Sawm is the fourth pillar of Islam  Fasting in the month of Ramadan  The Islamic calendar and Ramadan  What is fasting? (No food, drink from dawn to sunset)  Who must fast? (Conditions)  Suhoor (pre-dawn meal) and Iftar (breaking fast)  Simple rules of fasting"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,808) on conflict (id) do nothing;
