insert into curriculum_topics values ('P4-islamic-studies-t2-w8','ng-scheme-2025-preprimary-primary','P4','islamic-studies',2,'8',8,'teaching',null,'Prophet Muhammad (SAW) - Part 1','[" Introduction to Ulul Azm (The Great Prophets)  Prophet Muhammad (SAW)", "The Last Prophet  Birth in Makkah (Year of the Elephant)  Orphaned early: father died before birth, mother died when he was 6  Raised by grandfather Abdul-Muttalib, then uncle Abu Talib  Known as Al-Amin (The Trustworthy)  Life before prophethood"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,809) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-islamic-studies-t2-w9','ng-scheme-2025-preprimary-primary','P4','islamic-studies',2,'9',9,'teaching',null,'Prophet Muhammad (SAW) - Part 2','[" Receiving the first revelation at age 40  Angel Jibril in Cave Hira  The beginning of prophethood  Preaching Islam in Makkah  Persecution of early Muslims  Patience and perseverance  Hijrah (Migration) to Madinah  Establishing the Islamic state in Madinah"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,809) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-islamic-studies-t2-w10','ng-scheme-2025-preprimary-primary','P4','islamic-studies',2,'10',10,'teaching',null,'Prophet Muhammad (SAW) - Part 3','[" Life in Madinah  Building the first mosque  Spreading Islam peacefully  The Prophet''s character: kindness, honesty, mercy  Treatment of family, companions, and even enemies  Final sermon and lessons  Death of the Prophet (SAW)  Following the Prophet''s example (Sunnah)"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,809) on conflict (id) do nothing;
