insert into curriculum_topics values ('P4-islamic-studies-t3-w1','ng-scheme-2025-preprimary-primary','P4','islamic-studies',3,'1',1,'teaching',null,'Zakat (Obligatory Charity)','[" Introduction to Zakat  Zakat is the third pillar of Islam  Meaning: Purification and growth  Who must pay Zakat? (Conditions)  Types of wealth subject to Zakat  Who receives Zakat? (Eight categories)  Difference between Zakat and Sadaqah  Blessings and benefits of giving Zakat  Caring for the poor and needy"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,811) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-islamic-studies-t3-w2','ng-scheme-2025-preprimary-primary','P4','islamic-studies',3,'2',2,'teaching',null,'Hajj (Pilgrimage) - Part 1','[" Introduction to Hajj  Hajj is the fifth pillar of Islam  Pilgrimage to the sacred city of Makkah  Performed in the month of Dhul-Hijjah  Who must perform Hajj? (Conditions: adult, sane, able, financially capable)  The Kaaba: The House of Allah  Ihram: Special clothing for Hajj  Once in a lifetime obligation"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,811) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-islamic-studies-t3-w3','ng-scheme-2025-preprimary-primary','P4','islamic-studies',3,'3',3,'teaching',null,'Hajj (Pilgrimage) - Part 2','[" Major rituals of Hajj  Tawaf: Circling the Kaaba seven times  Sa''i: Walking between Safa and Marwah  Standing at Arafat (most important ritual)  Stoning the pillars at Mina  Sacrificing an animal (Eid-ul-Adha)  Shaving or cutting hair  Spiritual benefits and lessons from Hajj  Unity of Muslims from all over the world"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,811) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-islamic-studies-t3-w4','ng-scheme-2025-preprimary-primary','P4','islamic-studies',3,'4',4,'teaching',null,'Prophet Nuh (AS) - Noah','[" Introduction to Prophet Nuh (AS)  One of the Ulul Azm (Great Prophets)  His people worshipped idols  Nuh called them to worship Allah alone  Preached for 950 years with patience  Very few people believed  Allah commanded him to build the Ark  The great flood and saving the believers  Lessons: Patience, perseverance, trust in Allah"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,811) on conflict (id) do nothing;
