insert into curriculum_topics values ('P4-islamic-studies-t3-w7','ng-scheme-2025-preprimary-primary','P4','islamic-studies',3,'7',7,'teaching',null,'Prophet Ibrahim (AS) - Abraham - Part 1','[" Introduction to Prophet Ibrahim (AS)  Father of Prophets, one of Ulul Azm  Born in a land of idol worshippers  Questioned idol worship from childhood  Breaking the idols and being thrown in fire  Allah saved him from the fire  His strong faith in Allah  Migration for the sake of Allah"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,812) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-islamic-studies-t3-w8','ng-scheme-2025-preprimary-primary','P4','islamic-studies',3,'8',8,'teaching',null,'Prophet Ibrahim (AS) - Abraham - Part 2','[" Building the Kaaba with his son Ismail  The test: Commanded to sacrifice his son  Both Ibrahim and Ismail submitted to Allah''s will  Allah replaced Ismail with a ram  Origin of Eid-ul-Adha sacrifice  Lessons: Complete submission to Allah, trust, obedience  Ibrahim as a role model for believers"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,812) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-islamic-studies-t3-w9','ng-scheme-2025-preprimary-primary','P4','islamic-studies',3,'9',9,'teaching',null,'Prophet Musa (AS) - Moses & Prophet Isa (AS) - Jesus','["Prophet Musa (AS):  Birth during Pharaoh''s persecution  Saved by Allah and raised in Pharaoh''s palace  Called to prophethood at Mount Sinai  Sent to Pharaoh with message of Allah  The miracles: staff turning to snake, splitting of Red Sea  Receiving the Torah  Leading Bani Israel Prophet Isa (AS):  Miraculous birth to Maryam (Virgin Mary)  Born without a father by Allah''s command  Given many miracles: healing the sick, raising the dead  Received the Injil (Gospel)  Not crucified - Allah raised him to heaven  Will return before the Day of Judgment"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,812) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-islamic-studies-t3-w10','ng-scheme-2025-preprimary-primary','P4','islamic-studies',3,'10',10,'teaching',null,'Moral Virtues in Islam - Part 1','[" Introduction to moral virtues (good character)  Truthfulness (Sidq): Always telling the truth  Honesty (Amanah): Being trustworthy  Patience (Sabr): Enduring difficulties  Gratitude (Shukr): Being thankful to Allah  Kindness (Ihsan): Being good to all  Justice (Adl): Being fair  Examples from Prophet Muhammad''s life"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,812) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-islamic-studies-t3-w11','ng-scheme-2025-preprimary-primary','P4','islamic-studies',3,'11',11,'teaching',null,'Moral Virtues in Islam - Part 2 & Moral Vices','[" More Virtues:  Humility (Tawadu): Not being proud  Generosity (Karam): Giving to others  Courage (Shuja''ah): Bravery in doing right  Forgiveness (Afw): Pardoning others  Moral Vices (Bad behaviors to avoid):  Lying (Kidhb)  Stealing (Sariqah)  Backbiting (Ghibah)  Pride and arrogance (Kibr)  Jealousy (Hasad)  Anger (Ghadab)  Laziness (Kasal)  Being a good Muslim by avoiding vices and practicing virtues"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,813) on conflict (id) do nothing;
