insert into curriculum_topics values ('P4-french-language-t1-w1','ng-scheme-2025-preprimary-primary','P4','french-language',1,'1',1,'teaching',null,'Pourquoi apprendre le français? (Why learn French?)','[" Importance of learning French: international language, career opportunities  French-speaking countries in Africa: Senegal, Côte d''Ivoire, Benin, Togo, Niger, Mali, etc.  French in Nigeria: neighboring countries, international relations, education  Basic French greetings: Bonjour, Bonsoir, Salut  Introduction to French alphabet and pronunciation  Motivating students: French songs, cartoons, famous French speakers"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,835) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-french-language-t1-w2','ng-scheme-2025-preprimary-primary','P4','french-language',1,'2',2,'teaching',null,'Saluer (Greetings) - Part 1','[" Formal greetings: Bonjour (Good morning/day), Bonsoir (Good evening), Bonne nuit (Good night)  Informal greetings: Salut (Hi), Coucou (Hey)  Asking \"How are you?\": Comment allez-vous? (formal), Comment ça va? (informal)  Responses: Ça va bien (I''m fine), Très bien (Very well), Comme ci comme ça (So-so)  Practice dialogues with greetings"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,835) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-french-language-t1-w3','ng-scheme-2025-preprimary-primary','P4','french-language',1,'3',3,'teaching',null,'Saluer (Greetings) - Part 2','[" Saying goodbye: Au revoir (Goodbye), À bientôt (See you soon), À demain (See you tomorrow)  Polite expressions: S''il vous plaît (Please), Merci (Thank you), De rien (You''re welcome), Excusez-moi (Excuse me), Pardon (Sorry)  Role-playing greetings in different situations  Greeting songs and rhymes  Cultural note: French greeting customs (handshakes, \"la bise\")"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,835) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-french-language-t1-w4','ng-scheme-2025-preprimary-primary','P4','french-language',1,'4',4,'teaching',null,'Se présenter (Introducing Oneself) - Part 1','[" Saying your name: Je m''appelle... (My name is...), Je suis... (I am...)  Asking someone''s name: Comment tu t''appelles? (What''s your name? - informal), Comment vous appelez-vous? (formal)  Stating nationality: Je suis nigérian(e) (I am Nigerian)  Basic personal pronouns: Je (I), Tu (You - informal), Vous (You - formal), Il (He), Elle (She)  Practice introducing yourself and asking others'' names"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,835) on conflict (id) do nothing;
