insert into curriculum_topics values ('P4-french-language-t1-w7','ng-scheme-2025-preprimary-primary','P4','french-language',1,'7',7,'teaching',null,'Se présenter (Introducing Oneself) - Part 2','[" Stating age: J''ai ... ans (I am ... years old), Quel âge as-tu? (How old are you?)  Numbers 1-20 in French (for age): un, deux, trois, quatre, cinq, six, sept, huit, neuf, dix, onze, douze, treize, quatorze, quinze, seize, dix-sept, dix-huit, dix-neuf, vingt  Gender: Je suis un garçon (I am a boy), Je suis une fille (I am a girl)  Practice complete self-introductions  Listening exercises with introductions"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,836) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-french-language-t1-w8','ng-scheme-2025-preprimary-primary','P4','french-language',1,'8',8,'teaching',null,'Prendre congé (Taking Leave) - Part 1','[" Various ways to say goodbye: Au revoir, Adieu (Farewell), Salut (Bye - informal)  Time-specific farewells: À tout à l''heure (See you later - today), À ce soir (See you tonight), À la prochaine (Until next time)  Wishing well: Bonne journée (Have a good day), Bon week-end (Have a good weekend), Bonnes vacances (Have a good holiday)  Appropriate farewells for different times and situations"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,836) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-french-language-t1-w9','ng-scheme-2025-preprimary-primary','P4','french-language',1,'9',9,'teaching',null,'Prendre congé (Taking Leave) - Part 2','[" Expressing gratitude when leaving: Merci beaucoup (Thank you very much), Merci pour tout (Thank you for everything)  Combined greetings and farewells in dialogues  Cultural differences in taking leave (French vs", "Nigerian customs)  Role-play: complete conversations from greeting to farewell  Creating dialogues in pairs and groups"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,836) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-french-language-t1-w10','ng-scheme-2025-preprimary-primary','P4','french-language',1,'10',10,'teaching',null,'Review and Integration: Identity Theme','[" Comprehensive review of all identity/identification topics  Creating personal identity cards in French (name, age, nationality)  Class presentations: students introduce themselves completely  Group dialogues: meeting, greeting, introducing, saying goodbye  French pronunciation practice and correction  French language games: \"Je m''appelle\" game, greeting relay"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,836) on conflict (id) do nothing;
