insert into curriculum_topics values ('P4-french-language-t2-w1','ng-scheme-2025-preprimary-primary','P4','french-language',2,'1',1,'teaching',null,'Présenter les membres de la famille proche (Presenting Close Family Members)','["Part 1", " Introduction to family vocabulary:", "La famille (family), Le père/papa (father/dad), La mère/maman (mother/mom)", "Le frère (brother), La sœur (sister)  Introducing family: Voici mon père (This is my father), C''est ma mère (This is my mother)  Possessive adjectives: mon (my - masculine), ma (my - feminine), mes (my - plural)  Simple sentences about family: J''ai un frère (I have a brother)"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,838) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-french-language-t2-w2','ng-scheme-2025-preprimary-primary','P4','french-language',2,'2',2,'teaching',null,'Présenter les membres de la famille proche (Presenting Close Family Members)','["Part 2", " Extended family vocabulary:", "Le grand-père (grandfather), La grand-mère (grandmother)", "L''oncle (uncle), La tante (aunt), Le cousin/La cousine (cousin)", "Les parents (parents), Les grands-parents (grandparents)  Talking about family members: Il s''appelle... (His name is...), Elle s''appelle... (Her name is...)  Numbers review and counting family members  Drawing and presenting family trees in French"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,838) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-french-language-t2-w3','ng-scheme-2025-preprimary-primary','P4','french-language',2,'3',3,'teaching',null,'Présenter les membres de la famille proche (Presenting Close Family Members)','["Part 3", " Describing family members (basic): grand(e) (big/tall), petit(e) (small/short), jeune (young), vieux/vieille (old)  Family relationships: Mon père et ma mère sont mes parents (My father and mother are my parents)  Verb \"avoir\" (to have) - present tense: J''ai, Tu as, Il/Elle a  Creating family descriptions: J''ai deux frères et une sœur (I have two brothers and one sister)  Family-themed songs and rhymes"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,838) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-french-language-t2-w4','ng-scheme-2025-preprimary-primary','P4','french-language',2,'4',4,'teaching',null,'Parler de l''école (Talking about School) - Part 1','[" School vocabulary:", "L''école (school), La classe (classroom), Le/La professeur(e) (teacher)", "L''élève (student), Le tableau (board), Le bureau (desk/office)", "Le cahier (notebook), Le livre (book), Le stylo (pen), Le crayon (pencil)  Saying where you study: Je vais à l''école (I go to school), J''étudie à... (I study at...)  Simple school sentences: Voici mon école (This is my school)"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,839) on conflict (id) do nothing;
