insert into curriculum_topics values ('P4-french-language-t2-w7','ng-scheme-2025-preprimary-primary','P4','french-language',2,'7',7,'teaching',null,'Parler de l''école (Talking about School) - Part 2','[" More school vocabulary:", "La bibliothèque (library), La cour de récréation (playground)", "La salle de classe (classroom), Le directeur/La directrice (headteacher)", "Les matières (subjects): français, anglais, mathématiques, sciences  School subjects: J''aime le français (I like French), J''étudie les mathématiques (I study mathematics)  Verb \"aller\" (to go) - present tense: Je vais, Tu vas, Il/Elle va"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,839) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-french-language-t2-w8','ng-scheme-2025-preprimary-primary','P4','french-language',2,'8',8,'teaching',null,'Parler de l''école (Talking about School) - Part 3','[" School activities vocabulary: - Étudier (to study), Lire (to read), Écrire (to write), Écouter (to listen)", "Parler (to speak), Apprendre (to learn), Jouer (to play)  Days of the week: lundi, mardi, mercredi, jeudi, vendredi, samedi, dimanche  School schedule: Le lundi, j''ai français (On Monday, I have French)  Describing school day: À l''école, je lis et j''écris (At school, I read and write)"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,839) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-french-language-t2-w9','ng-scheme-2025-preprimary-primary','P4','french-language',2,'9',9,'teaching',null,'Parler de l''école (Talking about School) - Part 4','[" School locations and directions:", "Où est...? (Where is...?), Voici/Voilà (Here is/There is) - À côté de (next to), Devant (in front of), Derrière (behind)  Colors in French: rouge (red), bleu(e) (blue), jaune (yellow), vert(e) (green), noir(e) (black), blanc(he) (white)  Describing school items: Mon cahier est rouge (My notebook is red)  Creating \"Mon école\" (My school) posters and presentations"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,840) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-french-language-t2-w10','ng-scheme-2025-preprimary-primary','P4','french-language',2,'10',10,'teaching',null,'Review and Integration: Immediate Environment Theme','[" Comprehensive review of family and school vocabulary  Creating family presentations in French  School tour descriptions in French  Role-play: introducing family members to teachers/friends  Dialogues: talking about school experiences  French language games: family bingo, school vocabulary matching"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,840) on conflict (id) do nothing;
