insert into curriculum_topics values ('P4-french-language-t3-w1','ng-scheme-2025-preprimary-primary','P4','french-language',3,'1',1,'teaching',null,'Compter de 0 à 20 (Counting from 0 to 20) - Part 1','[" Numbers 0-10 review and practice:  zéro (0), un (1), deux (2), trois (3), quatre (4), cinq (5), six (6), sept (7), huit (8), neuf (9), dix (10)  Pronunciation practice for each number  Counting objects in classroom  Simple math in French: deux plus trois égale cinq (2 + 3 = 5)  Number songs and rhymes"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,841) on conflict (id) do nothing;
